/* ================= 虚词“其”与句末语气词 ================= */
{
  id: 'w-qi', title: '虚词“其”与常见句末语气词', short: '虚词·其', module: 'wenyan', grade: 8, freq: 2,
  prereqs: ['w-zhi'],
  tip: '“其”除了作代词，还能表示推测、反问，常考辨析；句末语气词决定句子的语气，翻译时要译出“吗”“呢”“啊”“罢了”等，不能丢。',
  learn: [
    { h: '“其”作代词：先问“谁的”', html: `
      <table class="tbl">
        <tr><th>用法</th><th>例句（出处）</th><th>解释</th></tr>
        <tr><td>他（她、它）的，他们的</td><td>屠自后断其股（《狼》）<br>其妻献疑曰（《愚公移山》）<br>恐前后受其敌（《狼》）</td><td>狼的（大腿）<br>愚公的（妻子）<br>它们（两只狼）的</td></tr>
        <tr><td>他（它、他们）</td><td>安求其能千里也（《马说》）</td><td>它（千里马）</td></tr>
        <tr><td>其中的</td><td>其一犬坐于前（《狼》）<br>择其善者而从之（《论语》十二章）</td><td>其中一只（狼）<br>（他们）其中好的方面</td></tr>
        <tr><td>那，这（指示代词）</td><td>其岸势犬牙差互（《小石潭记》）</td><td>那（溪水的）两岸</td></tr>
      </table>
      <p>做题时先问：“其”指的是谁？把它换成具体的人或物，读通了就对了。</p>` },
    { h: '“其”表语气：大概、难道', html: `
      <table class="tbl">
        <tr><th>用法</th><th>例句（出处）</th><th>解释</th></tr>
        <tr><td>表推测：大概、恐怕</td><td>其真不知马也（《马说》）<br>其必曰“先天下之忧而忧，后天下之乐而乐”乎（《岳阳楼记》）</td><td>恐怕是真的不识得千里马吧<br>他们大概一定会说……吧</td></tr>
        <tr><td>表反问：难道、怎么</td><td>其真无马邪（《马说》）<br>其如土石何（《愚公移山》）</td><td>难道真的没有千里马吗<br>又能把土石怎么样呢（“其”加强反问语气，可译为“又”“还”）</td></tr>
      </table>
      <p class="ex">呜呼！其真无马邪？其真不知马也！（《马说》）<span class="zh">唉！难道真的没有千里马吗？恐怕是他们真的不识得千里马吧！</span></p>
      <p class="warn">一句之中两个“其”，意思不同：前一个配“邪”（吗），是反问“难道”；后一个配“也”，是推测“恐怕”。<b>看句末</b>是判断“其”的好帮手。</p>` },
    { h: '句末语气词', html: `
      <table class="tbl">
        <tr><th>词</th><th>例句（出处）</th><th>语气 / 翻译</th></tr>
        <tr><td>也</td><td>夫战，勇气也（《曹刿论战》）</td><td>表判断，可不译或译为“是”</td></tr>
        <tr><td>矣</td><td>骨已尽矣（《狼》）</td><td>了</td></tr>
        <tr><td>乎</td><td>传不习乎（《论语》十二章）<br>大兄何见事之晚乎（《孙权劝学》）</td><td>吗（疑问）<br>呢（疑问）</td></tr>
        <tr><td>哉</td><td>贤哉，回也（《论语》十二章）<br>禽兽之变诈几何哉（《狼》）</td><td>啊（感叹）<br>呢（疑问、反问）</td></tr>
        <tr><td>耳 / 尔</td><td>止增笑耳（《狼》）<br>但手熟尔（《卖油翁》）</td><td>罢了</td></tr>
        <tr><td>邪（耶）</td><td>孤岂欲卿治经为博士邪（《孙权劝学》）</td><td>吗（常和“岂”配合表反问）</td></tr>
        <tr><td>与（欤）</td><td>所识穷乏者得我与（《鱼我所欲也》）</td><td>吗</td></tr>
        <tr><td>夫</td><td>逝者如斯夫（《论语》十二章）</td><td>啊（感叹）</td></tr>
      </table>
      <p class="warn">“夫”在句首是发语词，不译（夫战，勇气也）；在句末是语气词，表感叹（逝者如斯夫）。“乎”在句中可以相当于“于”：醉翁之意不在酒，在乎山水之间也（《醉翁亭记》）——在于山水之间。</p>` },
    { h: '多面手“焉”', html: `
      <table class="tbl">
        <tr><th>用法</th><th>例句（出处）</th><th>解释</th></tr>
        <tr><td>疑问代词：哪里，怎么</td><td>且焉置土石（《愚公移山》）</td><td>况且把土石放到哪里呢</td></tr>
        <tr><td>兼词：于此，在其中</td><td>三人行，必有我师焉（《论语》十二章）</td><td>其中一定有可以做我老师的人</td></tr>
        <tr><td>句末语气词，可不译</td><td>可远观而不可亵玩焉（《爱莲说》）</td><td>只可以远远地观赏，而不能靠近玩弄</td></tr>
      </table>
      <div class="rhyme">“其”字先问是谁的，<br>配“邪”难道配“也”恐；<br>乎吗哉啊耳罢了，<br>矣是了来也判断；<br>夫在句首不用译，<br>句末感叹记心中。</div>` }
  ],
  examples: [
    { type: 'choice', q: '“呜呼！<span class="dot-em">其</span>真无马邪？<span class="dot-em">其</span>真不知马也！”（《马说》）中两个“其”的意思，正确的一项是：', options: [
        '前一个表反问，难道；后一个表推测，恐怕',
        '前一个表推测，恐怕；后一个表反问，难道',
        '两个都是代词，他们',
        '两个都表反问，难道'], answer: 0,
      explain: '第一句句末是“邪”（吗），“其”表反问，译为“难道”；第二句句末是“也”，“其”表推测，译为“恐怕”。这是作者对“天下无马”的有力反驳。' },
    { type: 'open', q: '翻译：“狼亦黠矣，而顷刻两毙，禽兽之变诈几何哉？止增笑耳。”（《狼》）',
      ref: '<p>狼也太狡猾了，可是一会儿两只狼都被杀死了，禽兽的欺骗手段能有多少呢？只是给人增加笑料罢了。</p>',
      points: [{ s: 1, p: '“黠”译为“狡猾”，“顷刻”译为“一会儿”' }, { s: 1, p: '“几何哉”译为“能有多少呢”，译出疑问语气' }, { s: 1, p: '“止”译为“只”，“耳”译为“罢了”' }] },
    { type: 'choice', q: '“<span class="dot-em">其</span>妻献疑曰”（《愚公移山》）和“<span class="dot-em">其</span>一犬坐于前”（《狼》）中两个“其”，正确的一项是：', options: [
        '前一个是“他的”（愚公的）；后一个是“其中的”',
        '两个都是“他的”',
        '前一个是“其中的”；后一个是“他的”',
        '两个都表推测，“大概”'], answer: 0,
      explain: '先问“谁的”：“其妻”是愚公的妻子；“其一”是两只狼中的一只，“其”是“其中的”。把“其”换成具体的人或物，读通就对了。' },
    { type: 'choice', q: '“且欲与常马等不可得，安求<span class="dot-em">其</span>能千里也？”（《马说》）中“其”的意思是：', options: ['它（指千里马）', '他的（指喂马的人的）', '难道', '大概'], answer: 0,
      explain: '想要和普通的马一样尚且办不到，怎么能要求它日行千里呢？“其”作“能千里”的主语，指千里马，译为“它”。' },
    { type: 'open', q: '翻译：“（古仁人）其必曰‘先天下之忧而忧，后天下之乐而乐’乎！”（《岳阳楼记》）并说说“其”表示什么语气。',
      ref: '<p>翻译：他们大概一定会说“在天下人忧虑之前先忧虑，在天下人快乐之后才快乐”吧。</p><p>语气：“其”与句末的“乎”配合，表示推测，译为“大概”。</p>',
      points: [{ s: 1, p: '“其”译为“大概”，句末“乎”译为“吧”' }, { s: 1, p: '“先天下之忧而忧，后天下之乐而乐”译为“在天下人忧虑之前先忧虑，在天下人快乐之后才快乐”' }, { s: 1, p: '指出“其”表推测语气' }],
      explain: '看句末来判断“其”：这里是作者推测古仁人会怎么说，句末“乎”相当于“吧”，“其”表推测。' },
    { type: 'choice', q: '“夫战，勇气<span class="dot-em">也</span>”（《曹刿论战》）和“骨已尽<span class="dot-em">矣</span>”（《狼》）中两个句末语气词的作用，正确的一项是：', options: [
        '也：表判断；矣：相当于“了”',
        '也：相当于“了”；矣：表判断',
        '也：表疑问；矣：表感叹',
        '都表疑问，相当于“吗”'], answer: 0,
      explain: '“夫战，勇气也”是判断句：作战靠的是勇气，“也”表判断。“骨已尽矣”是骨头已经扔完了，“矣”相当于“了”。' },
    { type: 'choice', q: '“传不习<span class="dot-em">乎</span>”（《论语》十二章）和“所识穷乏者得我<span class="dot-em">与</span>”（《鱼我所欲也》）中两个句末语气词，正确的一项是：', options: [
        '都表疑问，相当于“吗”',
        '乎：啊；与：和',
        '乎：于；与：给',
        '都表感叹，相当于“啊”'], answer: 0,
      explain: '“传不习乎”是老师传授的知识是不是复习了呢（吗）；“得我与”是为了让认识的穷人感激我吗，“与”同“欤”，表疑问。' },
    { type: 'open', q: '翻译：“孤岂欲卿治经为博士邪！”（《孙权劝学》）',
      ref: '<p>我难道想要你研究儒家经典成为传授经学的学官吗！</p>',
      points: [{ s: 1, p: '“岂……邪”译为“难道……吗”，译出反问语气' }, { s: 1, p: '“治经”译为“研究儒家经典”，“为博士”译为“成为博士（传授经学的学官）”' }],
      explain: '“邪”常和“岂”配合表反问：难道……吗？翻译时一定要译出反问语气。' },
    { type: 'choice', q: '“<span class="dot-em">夫</span>战，勇气也”（《曹刿论战》）和“逝者如斯<span class="dot-em">夫</span>”（《论语》十二章）中两个“夫”，正确的一项是：', options: [
        '前一个是句首发语词，不译；后一个是句末语气词，表感叹，相当于“啊”',
        '两个都是“丈夫”',
        '两个都是句首发语词，不译',
        '前一个表感叹；后一个是发语词'], answer: 0,
      explain: '“夫”在句首，引起下文议论，不译；在句末，表感叹：消逝的时光就像这河水一样啊。看位置就能分清。' },
    { type: 'open', q: '翻译：“醉翁之意不在酒，在乎山水之间也。”（《醉翁亭记》）',
      ref: '<p>醉翁的情趣不在于喝酒，而在于欣赏山水的美景。</p>',
      points: [{ s: 1, p: '“意”译为“情趣（意趣）”' }, { s: 1, p: '“在乎”的“乎”相当于“于”，“在乎”译为“在于”' }],
      explain: '“乎”用在句中，不表疑问，相当于介词“于”。不能把这句译成疑问句。' },
    { type: 'choice', q: '“三人行，必有我师<span class="dot-em">焉</span>”（《论语》十二章）和“可远观而不可亵玩<span class="dot-em">焉</span>”（《爱莲说》）中两个“焉”，正确的一项是：', options: [
        '前一个是兼词，相当于“于此（在其中）”；后一个是句末语气词，可不译',
        '两个都是“哪里”',
        '前一个是“怎么”；后一个是“哪里”',
        '两个都是疑问代词，相当于“怎么”'], answer: 0,
      explain: '“必有我师焉”是几个人同行，其中一定有可以做我老师的人，“焉”相当于“于此”，在其中。“可远观而不可亵玩焉”的“焉”在句末，只起语气作用，可不译。' }
  ],
  tests: [
    { type: 'choice', q: '“其真不知马也”中，“其”的意思是：', options: ['恐怕，大概（表推测）', '难道（表反问）', '他的', '那个'], answer: 0,
      explain: '句末是“也”，作者推测地下结论：恐怕是真的不识得千里马吧。' },
    { type: 'choice', q: '“其真无马邪”中，“其”的意思是：', options: ['难道（表反问）', '恐怕（表推测）', '他们的', '其中的'], answer: 0,
      explain: '句末是“邪”（吗），“其……邪”表反问：难道真的没有千里马吗？' },
    { type: 'choice', q: '“身已半入，止露尻尾。屠自后断<span class="dot-em">其</span>股”（《狼》）中，“其”指代的是：', options: ['钻进柴草堆打洞的那只狼', '屠户', '假装睡觉的那只狼', '麦场的主人'], answer: 0,
      explain: '屠户从后面砍断了那只正在打洞的狼的大腿，“其”是“它的”，指打洞的狼。' },
    { type: 'fill', q: '解释加点词：禽兽之变诈几何哉？止增笑<span class="dot-em">耳</span>。（《狼》）', answer: ['罢了', '而已'],
      explain: '“耳”是句末语气词，相当于“罢了”。' },
    { type: 'choice', q: '“以君之力，曾不能损魁父之丘，如太行、王屋何？且<span class="dot-em">焉</span>置土石？”（《愚公移山》）中，“焉”的意思是：', options: ['哪里', '于此，在这里', '句末语气词，不译', '于是'], answer: 0,
      explain: '“焉置土石”即“置土石于何处”：把土石放到哪里？“焉”是疑问代词“哪里”。' },
    { type: 'fill', q: '解释加点词：贤<span class="dot-em">哉</span>，回也！（《论语》十二章）', answer: ['啊', '呀', '呀表感叹', '啊表感叹'],
      explain: '孔子称赞颜回贤德，“哉”表感叹，相当于“啊”。' },
    { type: 'choice', q: '下列对加点词的解说，<b>有误</b>的一项是：', options: [
        '传不习<span class="dot-em">乎</span>——乎，吗，表疑问',
        '骨已尽<span class="dot-em">矣</span>——矣，了',
        '<span class="dot-em">夫</span>战，勇气也——夫，句首发语词，不译',
        '在<span class="dot-em">乎</span>山水之间也——乎，吗，表疑问'], answer: 3,
      explain: '“在乎山水之间也”的“乎”用在句中，相当于“于”，“在乎”即“在于”，不是表疑问。' },
    { type: 'fill', q: '“<span class="dot-em">其</span>妻献疑曰”（《愚公移山》）中，“其”指代的是：', answer: ['愚公的', '愚公', '他的', '北山愚公的', '北山愚公'],
      explain: '“其妻”是愚公的妻子，“其”是“他的”，指愚公。' },
    { type: 'choice', q: '“安求<span class="dot-em">其</span>能千里也”中“其”的用法是：', options: ['代词，它，指千里马', '表推测，大概', '表反问，难道', '其中的'], answer: 0,
      explain: '怎么能要求它日行千里呢？“其”指千里马。' },
    { type: 'fill', q: '解释加点词：<span class="dot-em">其</span>一犬坐于前。（《狼》）', answer: ['其中的', '其中', '它们中的', '其中一只', '两狼中的'],
      explain: '“其一”是其中一只（狼），“其”是“其中的”。' },
    { type: 'choice', q: '“三人行，必有我师焉。择<span class="dot-em">其</span>善者而从之”中，“其”的意思是：', options: ['（他们）其中的', '我的', '大概', '难道'], answer: 0,
      explain: '选择他们（同行的人）中好的方面学习，“其”指同行的人，是“他们的、其中的”，不是“我的”。' },
    { type: 'choice', q: '“<span class="dot-em">其</span>岸势犬牙差互，不可知其源”（《小石潭记》）中，第一个“其”所指的是：', options: ['溪水', '作者', '小石潭的游客', '竹林'], answer: 0,
      explain: '“其岸势”是那（溪水的）两岸的形状，“其”指溪水。' },
    { type: 'choice', q: '下列加点“其”的解释，<b>有误</b>的一项是：', options: [
        '<span class="dot-em">其</span>真不知马也：难道',
        '<span class="dot-em">其</span>必曰“先天下之忧而忧，后天下之乐而乐”乎：大概',
        '<span class="dot-em">其</span>岸势犬牙差互：那（指溪水）',
        '<span class="dot-em">其</span>真无马邪：难道'], answer: 0,
      explain: '“其真不知马也”句末是“也”，“其”表推测，是“恐怕”，不是“难道”。' },
    { type: 'choice', q: '“<span class="dot-em">其</span>必曰‘先天下之忧而忧，后天下之乐而乐’乎”中“其”的意思是：', options: ['大概', '难道', '他的', '其中的'], answer: 0,
      explain: '作者推测古仁人会怎么说，“其”表推测，译为“大概”，句末的“乎”可译为“吧”。' },
    { type: 'choice', q: '对“呜呼！其真无马邪？”的翻译，正确的一项是：', options: [
        '唉！难道真的没有千里马吗？',
        '唉！恐怕真的没有千里马吧！',
        '唉！他们真的没有马了！',
        '唉！真的有马吗？'], answer: 0,
      explain: '“其……邪”表反问，“其”译为“难道”，“邪”译为“吗”。' },
    { type: 'choice', q: '判断“其真无马邪”中“其”表反问还是推测，最有用的线索是：', options: [
        '句末的语气词“邪”（吗），配“邪”多表反问',
        '“其”在句首',
        '“其”后面有“真”字',
        '这句话出自《马说》'], answer: 0,
      explain: '“看句末”是判断“其”的好帮手：配“邪”（吗）是反问“难道”；配“也”是推测“恐怕”。' },
    { type: 'choice', q: '同在《马说》中，“其真无马邪”和“其真不知马也”两句里的“其”意思不同。造成不同的关键在于：', options: [
        '两句句末的语气词不同：“邪”表疑问，“也”表肯定',
        '两句“其”的读音不同',
        '两句“其”指代的人不同',
        '两句的主语不同'], answer: 0,
      explain: '句末“邪”是“吗”，“其”配合表反问，译为“难道”；句末“也”表肯定，“其”表推测，译为“恐怕”。' },
    { type: 'fill', q: '“夫战，勇气<span class="dot-em">也</span>”中的“也”表示什么语气？', answer: ['判断', '表判断', '判断语气', '肯定', '表肯定'],
      explain: '“……，……也”是判断句，“也”表判断，翻译时可译出“是”：作战，靠的是勇气。' },
    { type: 'choice', q: '“陈胜者，阳城人<span class="dot-em">也</span>”中“也”的作用是：', options: ['表判断，可不译', '表疑问，相当于“吗”', '表感叹，相当于“啊”', '相当于“了”'], answer: 0,
      explain: '“……者，……也”是典型的判断句，“也”表判断：陈胜是阳城人。' },
    { type: 'fill', q: '解释加点词：骨已尽<span class="dot-em">矣</span>，而两狼之并驱如故。（《狼》）', answer: ['了'],
      explain: '“矣”是句末语气词，相当于“了”。' },
    { type: 'fill', q: '解释加点词：与朋友交而不信<span class="dot-em">乎</span>？传不习乎？（《论语》十二章）', answer: ['吗', '呢'],
      explain: '“乎”在句末表疑问，相当于“吗”。' },
    { type: 'choice', q: '“禽兽之变诈几何<span class="dot-em">哉</span>？”中“哉”的作用是：', options: ['表疑问（反问），相当于“呢”', '表感叹，相当于“啊”', '表判断', '相当于“了”'], answer: 0,
      explain: '“几何”是“多少”，“几何哉”是“能有多少呢”，“哉”表疑问（反问）语气。' },
    { type: 'choice', q: '下列两句中“哉”的作用，正确的一项是：<div class="passage"><p class="noindent">①贤哉，回也！（《论语》十二章）　②禽兽之变诈几何哉？（《狼》）</p></div>', options: [
        '①表感叹，啊；②表疑问，呢',
        '①表疑问，呢；②表感叹，啊',
        '两个都表感叹',
        '两个都表疑问'], answer: 0,
      explain: '①孔子赞叹颜回贤德，“哉”表感叹；②“几何哉”问能有多少呢，“哉”表疑问。“哉”可以表感叹，也可以表疑问，要看句子语气。' },
    { type: 'choice', q: '“我亦无他，惟手熟<span class="dot-em">尔</span>”中“尔”的意思是：', options: ['罢了', '你', '这样', '吗'], answer: 0,
      explain: '“尔”同“耳”，句末语气词，相当于“罢了”。' },
    { type: 'fill', q: '解释加点词：孤岂欲卿治经为博士<span class="dot-em">邪</span>！（《孙权劝学》）', answer: ['吗', '呢'],
      explain: '“邪”是句末语气词，与“岂”配合表反问，相当于“吗”。' },
    { type: 'choice', q: '“其真无马<span class="dot-em">邪</span>”中“邪”的意思是：', options: ['吗', '邪恶', '啊', '罢了'], answer: 0,
      explain: '“邪”是句末语气词，表疑问，相当于“吗”，读 yé。' },
    { type: 'fill', q: '解释加点词：为宫室之美，妻妾之奉，所识穷乏者得我<span class="dot-em">与</span>？（《鱼我所欲也》）', answer: ['吗', '呢'],
      explain: '“与”同“欤”，句末语气词，表疑问，相当于“吗”。' },
    { type: 'choice', q: '“所识穷乏者得我<span class="dot-em">与</span>”中“与”的意思是：', options: ['同“欤”，吗', '和，跟', '给予', '参与'], answer: 0,
      explain: '“与”在句末，是语气词，同“欤”，表疑问。' },
    { type: 'fill', q: '解释加点词：子在川上曰：“逝者如斯<span class="dot-em">夫</span>，不舍昼夜。”（《论语》十二章）', answer: ['啊', '呀', '吧'],
      explain: '“夫”在句末，表感叹，相当于“啊”。' },
    { type: 'choice', q: '下列句子中，“夫”是句末语气词、表示感叹的一项是：', options: [
        '逝者如斯<span class="dot-em">夫</span>',
        '<span class="dot-em">夫</span>战，勇气也',
        '<span class="dot-em">夫</span>大国，难测也',
        '嗟<span class="dot-em">夫</span>！予尝求古仁人之心'], answer: 0,
      explain: '“逝者如斯夫”的“夫”在句末，表感叹。“夫战”“夫大国”的“夫”是句首发语词；“嗟夫”是叹词“唉”，是一个词。' },
    { type: 'fill', q: '解释加点词：醉翁之意不在酒，在<span class="dot-em">乎</span>山水之间也。（《醉翁亭记》）', answer: ['于', '相当于于', '在于'],
      explain: '“乎”用在句中，相当于介词“于”，“在乎”就是“在于”。' },
    { type: 'fill', q: '解释加点词：以君之力，曾不能损魁父之丘，如太行、王屋何？且<span class="dot-em">焉</span>置土石？（《愚公移山》）', answer: ['哪里', '何处', '什么地方', '哪儿'],
      explain: '“焉”是疑问代词，“哪里”：况且把土石放到哪里呢？' },
    { type: 'choice', q: '“三人行，必有我师<span class="dot-em">焉</span>”中“焉”的意思是：', options: ['于此，在其中（兼词）', '哪里', '怎么', '于是'], answer: 0,
      explain: '几个人同行，其中一定有可以做我老师的人。“焉”相当于“于此”，即“在其中”。' },
    { type: 'open', q: '翻译：“三人行，必有我师焉。”（《论语》十二章）（2 分）',
      ref: '<p>几个人同行，其中一定有可以做我老师的人。</p>',
      points: [{ s: 1, p: '“三人”译为“几个人”（三是虚指）' }, { s: 1, p: '“焉”译为“在其中（于此）”，“我师”译为“可以做我老师的人”' }],
      explain: '“三”在这里是虚数，表示几个人；“焉”是兼词，相当于“于此”，译为“在其中”。' },
    { type: 'choice', q: '“可远观而不可亵玩<span class="dot-em">焉</span>”（《爱莲说》）的翻译，最恰当的一项是：', options: [
        '（莲）只可以远远地观赏，却不可以靠近玩弄啊',
        '（莲）可以远远地观赏，却不可以到哪里去玩弄呢',
        '（莲）可以远远地观赏，也可以靠近玩弄',
        '（莲）可以从远处观赏，却不可以随便地赞美它'], answer: 0,
      explain: '“亵”是亲近而不庄重，“亵玩”是靠近玩弄；“而”表转折，译为“却”。句末的“焉”在陈述句里，不是疑问代词“哪里”，翻译时可不译或只译出语气。' },
    { type: 'choice', q: '下列加点“焉”的解释，<b>有误</b>的一项是：', options: [
        '可远观而不可亵玩<span class="dot-em">焉</span>：哪里',
        '且<span class="dot-em">焉</span>置土石：哪里',
        '三人行，必有我师<span class="dot-em">焉</span>：于此，在其中',
        '始一反<span class="dot-em">焉</span>：句末语气词，可不译'], answer: 0,
      explain: '“可远观而不可亵玩焉”是陈述句，“焉”是句末语气词，可不译，不是“哪里”。' }
  ]
},

/* ================= 文言句式（一）：判断句与省略句 ================= */
{
  id: 'w-jushi1', title: '文言句式（一）：判断句与省略句', short: '判断·省略句', module: 'wenyan', grade: 8, freq: 2,
  prereqs: ['w-intro', 'y-chengfen'],
  tip: '翻译题常把特殊句式设为得分点：判断句要译出“是”，省略句要把省掉的成分补出来，否则句意不完整。',
  learn: [
    { h: '判断句：古人很少用“是”', html: `
      <p>今天我们说“A 是 B”，古人一般不用“是”，而是靠<b>“者”“也”</b>等字来表示判断：</p>
      <p class="ex">陈胜者，阳城人也。（《陈涉世家》）<span class="zh">陈胜是阳城人。</span></p>
      <table class="tbl">
        <tr><th>格式</th><th>例句（出处）</th><th>翻译</th></tr>
        <tr><td>……者，……也</td><td>陈胜者，阳城人也（《陈涉世家》）</td><td>陈胜是阳城人</td></tr>
        <tr><td>……，……也</td><td>夫战，勇气也（《曹刿论战》）<br>城北徐公，齐国之美丽者也（《邹忌讽齐王纳谏》）</td><td>作战，靠的是勇气<br>城北的徐公是齐国的美男子</td></tr>
        <tr><td>……，……者也</td><td>莲，花之君子者也（《爱莲说》）</td><td>莲花是花中的君子</td></tr>
        <tr><td>问答式：……者谁？……也</td><td>作亭者谁？山之僧智仙也（《醉翁亭记》）</td><td>建造亭子的是谁？是山中的和尚智仙</td></tr>
        <tr><td>用“为”“乃”表判断</td><td>中峨冠而多髯者为东坡（《核舟记》）<br>当立者乃公子扶苏（《陈涉世家》）</td><td>……是苏东坡<br>应当继位的是公子扶苏</td></tr>
        <tr><td>用“非”表否定判断</td><td>卿今者才略，非复吴下阿蒙（《孙权劝学》）</td><td>不再是当年吴县的阿蒙了</td></tr>
        <tr><td>用副词“诚”“则”等加强判断</td><td>此诚危急存亡之秋也（《出师表》）<br>此则岳阳楼之大观也（《岳阳楼记》）</td><td>这确实是形势危急、决定存亡的时候<br>这就是岳阳楼的雄伟景象</td></tr>
      </table>
      <p class="warn">古文中的“是”多半是代词“这”：“是马也，虽有千里之能”（《马说》）——这样的马；“是吾剑之所从坠”（《刻舟求剑》）——这里是我的剑掉下去的地方。不要一见“是”就当成判断词。</p>` },
    { h: '省略句：古人爱“偷懒”', html: `
      <p>前面说过的人、事，后面常常省掉不说。翻译时要<b>补出来</b>，并用括号标出。</p>
      <table class="tbl">
        <tr><th>省略什么</th><th>例句（出处）</th><th>补出后</th></tr>
        <tr><td>省主语</td><td>见渔人，乃大惊（《桃花源记》）</td><td>（村里的人）见到渔人，于是非常惊讶</td></tr>
        <tr><td>省主语</td><td>便舍船，从口入（《桃花源记》）</td><td>（渔人）就离开船，从洞口进去</td></tr>
        <tr><td>省谓语</td><td>一鼓作气，再而衰，三而竭（《曹刿论战》）</td><td>第一次击鼓振作士气，第二次（击鼓）士气就衰弱了，第三次（击鼓）士气就耗尽了</td></tr>
        <tr><td>省宾语</td><td>便要还家（《桃花源记》）</td><td>就邀请（渔人）到自己家里去</td></tr>
        <tr><td>省介词</td><td>得之心而寓之酒也（《醉翁亭记》）</td><td>领会（于）心中，寄托（于）酒上</td></tr>
      </table>` },
    { h: '怎么补省略', html: `
      <ol>
        <li><b>看动作是谁做的</b>：一句话里有动作却找不到做动作的人，往前文找主语。“见渔人，乃大惊”——惊讶的不是渔人，而是桃花源里的人。</li>
        <li><b>看前后对称</b>：“一鼓作气，再而衰，三而竭”，第一句有“鼓”，后面两句照着补出“鼓”。</li>
        <li><b>补完读一遍</b>：补出来的成分要和上下文合得上，句子才通顺。</li>
      </ol>
      <p class="warn">易错点：《陈太丘与友期行》“过中不至，太丘舍去，去后乃至”——“不至”和“乃至”的主语都是“友人”，不是太丘。</p>
      <div class="rhyme">者也者也是判断，<br>“是”字多半当“这”看；<br>主谓宾介常省略，<br>前后找来补完全。</div>` }
  ],
  examples: [
    { type: 'choice', q: '下列句子中，属于<b>判断句</b>的一项是：', options: ['夫战，勇气也', '骨已尽矣', '何陋之有', '战于长勺'], answer: 0,
      explain: '“夫战，勇气也”是“……，……也”的判断句：作战，靠的是勇气。“骨已尽矣”是一般陈述句，“何陋之有”是宾语前置，“战于长勺”是状语后置。' },
    { type: 'open', q: '翻译并补出省略成分：“过中不至，太丘舍去，去后乃至。”（《陈太丘与友期行》）',
      ref: '<p>过了正午（友人）还没有到，陈太丘不再等候就离开了，（陈太丘）离开后（友人）才到。</p>',
      points: [{ s: 1, p: '补出“不至”“乃至”的主语“友人”' }, { s: 1, p: '“舍去”译为“不再等候就离开了”（舍：舍弃；去：离开）' }, { s: 1, p: '“乃”译为“才”，句意通顺' }] },
    { type: 'choice', q: '“陈胜者，阳城人也”（《陈涉世家》）和“莲，花之君子者也”（《爱莲说》）的翻译，正确的一项是：', options: [
        '陈胜是阳城人；莲花是花中的君子',
        '陈胜这个人，在阳城做人；莲花，花的君子的人',
        '陈胜的阳城人；莲花和君子',
        '陈胜者是阳城人也；莲是花之君子者也'], answer: 0,
      explain: '两句都是判断句：前一句是“……者，……也”，后一句是“……，……者也”。古人靠“者”“也”表示判断，翻译时要加上“是”，“者”“也”一般不译。' },
    { type: 'open', q: '翻译：“作亭者谁？山之僧智仙也。”（《醉翁亭记》）',
      ref: '<p>建造亭子的人是谁？是山里的和尚智仙。</p>',
      points: [{ s: 1, p: '“作亭者”译为“建造亭子的人”' }, { s: 1, p: '问答式判断句，答句译出“是……”：是山里的和尚智仙' }],
      explain: '这是问答式判断句：前面“……者谁”发问，后面“……也”回答。答句要译出“是”。' },
    { type: 'choice', q: '“当立者<span class="dot-em">乃</span>公子扶苏”（《陈涉世家》）中“乃”的意思是：', options: ['是', '才', '于是', '你的'], answer: 0,
      explain: '应当继位的是公子扶苏，“乃”在这里表判断，相当于“是”。注意它和“去后乃至”（才）不同。' },
    { type: 'open', q: '翻译：“此则岳阳楼之大观也。”（《岳阳楼记》）',
      ref: '<p>这就是岳阳楼的雄伟景象。</p>',
      points: [{ s: 1, p: '“则”译为“就是”，译出判断语气' }, { s: 1, p: '“大观”译为“雄伟景象（盛大壮观的景象）”' }],
      explain: '“……也”表判断，副词“则”加强判断语气，译为“就是”。' },
    { type: 'choice', q: '“楚人有涉江者，其剑自舟中坠于水，遽契其舟，曰：‘<span class="dot-em">是</span>吾剑之所从坠。’”（《刻舟求剑》）中“是”的意思是：', options: ['这里', '是（判断词）', '对的', '于是'], answer: 0,
      explain: '“是吾剑之所从坠”是“这里是我的剑掉下去的地方”，“是”是指示代词“这（这里）”。古文中的“是”多半是代词，不要一见“是”就当成判断词。' },
    { type: 'open', q: '翻译并补出省略成分：“一鼓作气，再而衰，三而竭。”（《曹刿论战》）',
      ref: '<p>第一次击鼓能振作士气，第二次（击鼓）士气就衰弱了，第三次（击鼓）士气就耗尽了。</p>',
      points: [{ s: 1, p: '按前后对称补出“再”“三”后面省略的“鼓”' }, { s: 1, p: '“再”译为“第二次”，“衰”“竭”译为“衰弱”“耗尽”' }],
      explain: '第一句有“鼓”，后两句照着结构补出“鼓”，这就是“看前后对称”的补省略方法。' },
    { type: 'choice', q: '“（村中人）见渔人，乃大惊，问所从来。具答之。便要还家。”（《桃花源记》）中“便要还家”省略了什么成分？', options: [
        '省略了宾语“渔人”，即“便要（渔人）还家”',
        '省略了谓语“走”',
        '省略了介词“于”',
        '没有省略'], answer: 0,
      explain: '“要”通“邀”，邀请谁？邀请渔人。动词“要”后面省略了宾语“渔人”，翻译时要补出：就邀请（渔人）到自己家里去。' },
    { type: 'open', q: '翻译并补出省略的介词：“山水之乐，得之心而寓之酒也。”（《醉翁亭记》）',
      ref: '<p>欣赏山水的乐趣，领会（在）心里，寄托（在）酒上。</p>',
      points: [{ s: 1, p: '补出“心”“酒”前省略的介词“于”，译为“在”' }, { s: 1, p: '“得”译为“领会”，“寓”译为“寄托”，句意通顺' }],
      explain: '原句是“得之（于）心而寓之（于）酒”，省略了两个“于”。' },
    { type: 'choice', q: '“见渔人，乃大惊”中，“见”和“惊”的主语是谁？用“看动作是谁做的”来判断，正确的一项是：', options: [
        '桃花源中的人：他们见到外来的渔人，所以非常惊讶',
        '渔人：渔人见到自己，非常惊讶',
        '太守：太守见到渔人，非常惊讶',
        '刘子骥：他见到渔人，非常惊讶'], answer: 0,
      explain: '“见渔人”的宾语就是渔人，所以做“见”这个动作的不是渔人，而是桃花源里的人。往前文找，前文写的是“其中往来种作”的村人。' }
  ],
  tests: [
    { type: 'choice', q: '下列句子中，<b>不是</b>判断句的一项是：', options: ['莲，花之君子者也', '陈胜者，阳城人也', '中峨冠而多髯者为东坡', '屠自后断其股'], answer: 3,
      explain: '“屠自后断其股”是叙述屠户的动作，不是判断。“莲，花之君子者也”用“……者也”，“陈胜者，阳城人也”用“……者，……也”，“中峨冠而多髯者为东坡”用“为”，都表判断。' },
    { type: 'choice', q: '“卿今者才略，<span class="dot-em">非</span>复吴下阿蒙！”（《孙权劝学》）中，“非”的意思是：', options: ['不是', '错误', '反对', '没有'], answer: 0,
      explain: '“非复吴下阿蒙”即“不再是吴县的阿蒙了”，“非”表否定判断。' },
    { type: 'choice', q: '“一鼓作气，再而衰，三而竭”中省略的成分是：', options: ['谓语“鼓”', '主语“齐人”', '宾语“之”', '介词“于”'], answer: 0,
      explain: '“再而衰，三而竭”即“再（鼓）而衰，三（鼓）而竭”，省略了谓语动词“鼓”。' },
    { type: 'fill', q: '补出省略的主语：“（　　）见渔人，乃大惊，问所从来。”（《桃花源记》）', answer: ['村中人', '村里的人', '村人', '桃花源中的人', '桃花源里的人', '桃源人', '此中人', '村民', '桃花源中人', '村中的人'],
      explain: '见到渔人而大吃一惊的，是桃花源里的人。' },
    { type: 'fill', q: '“山水之乐，得之心而寓之酒也”（《醉翁亭记》）中，“心”“酒”前面都省略了同一个介词，这个介词是：', answer: ['于'],
      explain: '即“得之（于）心而寓之（于）酒”，领会在心里，寄托在酒上。“于”是“在”。' },
    { type: 'choice', q: '对“此诚危急存亡之秋也”（《出师表》）的句式和“秋”的解释，正确的一项是：', options: [
        '判断句；“秋”指时候',
        '判断句；“秋”指秋天',
        '省略句；“秋”指时候',
        '倒装句；“秋”指秋天'], answer: 0,
      explain: '“……也”表判断，“诚”加强判断语气：这确实是形势危急、决定存亡的时候。“秋”指时候。' },
    { type: 'choice', q: '“<span class="dot-em">是</span>马也，虽有千里之能，食不饱，力不足”（《马说》）中，“是”的意思是：', options: ['这', '是（判断词）', '对，正确', '于是'], answer: 0,
      explain: '“是马”就是“这样的马”，“是”是指示代词“这”。古文中的“是”多半不是判断词。' },
    { type: 'choice', q: '下列句子中，句式与“陈胜者，阳城人也”<b>相同</b>的一项是：', options: [
        '城北徐公，齐国之美丽者也',
        '何陋之有',
        '战于长勺',
        '马之千里者'], answer: 0,
      explain: '“城北徐公，齐国之美丽者也”和“陈胜者，阳城人也”都是判断句。“何陋之有”是宾语前置，“战于长勺”是状语后置，“马之千里者”是定语后置。' },
    { type: 'open', q: '翻译：“城北徐公，齐国之美丽者也。”（《邹忌讽齐王纳谏》）（2 分）',
      ref: '<p>城北的徐公，是齐国的美男子。</p>',
      points: [{ s: 1, p: '判断句，译出“是”' }, { s: 1, p: '“美丽者”译为“美男子（长得美的人）”' }],
      explain: '“……，……者也”表判断，“者”可译为“……的人”。' },
    { type: 'choice', q: '“予谓菊，花之隐逸者也；牡丹，花之富贵者也；莲，花之君子者也。”（《爱莲说》）的句式是：', options: ['判断句', '被动句', '省略句', '宾语前置句'], answer: 0,
      explain: '三个分句都用“……，……者也”表判断：菊花是花中的隐士，牡丹是花中的富贵者，莲花是花中的君子。' },
    { type: 'choice', q: '“作亭者谁？山之僧智仙也。名之者谁？太守自谓也。”这几句的句式特点是：', options: [
        '问答式判断句，答句用“……也”表判断',
        '被动句，用“者”表被动',
        '倒装句，“谁”提到了句末',
        '省略句，省略了所有主语'], answer: 0,
      explain: '先用“……者谁”发问，再用“……也”回答，是问答式判断句：给亭子取名的是谁？是太守用自己的别号来命名的。' },
    { type: 'choice', q: '对“名之者谁？太守自谓也”的翻译，正确的一项是：', options: [
        '给亭子命名的是谁？是太守用自己的别号（醉翁）来命名的',
        '名字是谁的？太守自己叫的',
        '谁有名？太守自己说有名',
        '谁给他取名？太守自己说的'], answer: 0,
      explain: '“名之”是给它（亭子）命名；答句“太守自谓也”是判断句，译出“是”：是太守用自己的别号来命名的。' },
    { type: 'fill', q: '解释加点词：二世少子也，不当立，当立者<span class="dot-em">乃</span>公子扶苏。（《陈涉世家》）', answer: ['是', '就是', '乃是'],
      explain: '“乃”表判断，相当于“是”。' },
    { type: 'choice', q: '下列句子中，加点词表示<b>判断</b>的一项是：', options: [
        '中峨冠而多髯者<span class="dot-em">为</span>东坡',
        '武陵人捕鱼<span class="dot-em">为</span>业',
        '去后<span class="dot-em">乃</span>至',
        '<span class="dot-em">为</span>人谋而不忠乎'], answer: 0,
      explain: '“为东坡”是“是苏东坡”，“为”表判断。“捕鱼为业”的“为”是“作为”；“去后乃至”的“乃”是“才”；“为人谋”的“为”是“替”。' },
    { type: 'fill', q: '“卿今者才略，<span class="dot-em">非</span>复吴下阿蒙！”是否定判断句。“非复”的意思是：', answer: ['不再是', '不再是了', '已不再是'],
      explain: '“非”是“不是”，“复”是“再”，“非复”就是“不再是”：你现在的才干和谋略，不再是当年吴县的那个阿蒙了！' },
    { type: 'choice', q: '“管宁割席分坐，曰：‘子<span class="dot-em">非</span>吾友也。’”这句话的句式和意思是：', options: [
        '否定判断句：你不是我的朋友了',
        '肯定判断句：你是我的朋友',
        '疑问句：你不是我的朋友吗',
        '被动句：你被我当作朋友'], answer: 0,
      explain: '“非……也”表否定判断，译为“不是……”。' },
    { type: 'fill', q: '解释加点词：此<span class="dot-em">则</span>岳阳楼之大观也。（《岳阳楼记》）', answer: ['就是', '是', '便是'],
      explain: '副词“则”加强判断语气，“此则……也”就是“这就是……”。' },
    { type: 'fill', q: '解释加点词：（楚人）遽契其舟，曰：“<span class="dot-em">是</span>吾剑之所从坠。”', answer: ['这里', '这', '此处', '这儿'],
      explain: '“是”是指示代词，指刻记号的地方：这里是我的剑掉下去的地方。' },
    { type: 'choice', q: '“（渔人）便舍船，从口入。”（《桃花源记》）中，“舍船”“入”的主语是：', options: ['渔人', '村中人', '太守', '刘子骥'], answer: 0,
      explain: '前文写渔人发现山有小口，“仿佛若有光”，于是（渔人）离开船，从洞口进去。这里省略了主语“渔人”。' },
    { type: 'fill', q: '补出省略的成分：一鼓作气，再（　　）而衰，三（　　）而竭。（两个空填同一个字）', answer: ['鼓', '鼓鼓'],
      explain: '后两句承前省略了谓语“鼓”（击鼓）：再（鼓）而衰，三（鼓）而竭。' },
    { type: 'fill', q: '补出省略的宾语：（村中人）便要（　　）还家，设酒杀鸡作食。', answer: ['渔人', '他', '之'],
      explain: '“要”通“邀”，邀请的是渔人，动词后面省略了宾语“渔人”。' },
    { type: 'choice', q: '下列句子中，补出省略成分<b>不正确</b>的一项是：', options: [
        '便要还家——便要（太守）还家',
        '再而衰——再（鼓）而衰',
        '得之心而寓之酒也——得之（于）心而寓之（于）酒也',
        '见渔人，乃大惊——（村中人）见渔人，乃大惊'], answer: 0,
      explain: '“便要还家”邀请的是渔人，太守此时还没有出场，应补“渔人”。' },
    { type: 'choice', q: '“过中不至，太丘舍去，去后乃至。”中，“不至”和“乃至”的主语分别是：', options: [
        '友人；友人',
        '太丘；太丘',
        '友人；太丘',
        '元方；友人'], answer: 0,
      explain: '是友人过了正午没到，太丘离开后友人才到。这是课内省略句的易错点，不要误以为是太丘。' },
    { type: 'choice', q: '“一鼓作气，再而衰，三而竭”中，能补出后两句省略的“鼓”，主要依据的方法是：', options: [
        '看前后对称：后两句结构和第一句相同，照着补出“鼓”',
        '看动作是谁做的',
        '看句末语气词',
        '看有没有“之”字'], answer: 0,
      explain: '“一鼓”“再（鼓）”“三（鼓）”是对称的结构，按第一句补出后两句省略的成分。' },
    { type: 'open', q: '“元方时年七岁，门外戏。客问元方：‘尊君在不？’答曰：‘待君久不至，已去。’”请补出“答曰”和“已去”的主语，并说明你是怎样判断的。（2 分）',
      ref: '<p>“答曰”的主语是元方，“已去”的主语是陈太丘（尊君、家父）。判断方法：客人问的是元方，所以回答的是元方；客人问“尊君在不”，回答“已去”说的是父亲已经离开了。</p>',
      points: [{ s: 1, p: '“答曰”的主语是元方，“已去”的主语是陈太丘（元方的父亲）' }, { s: 1, p: '说出依据：根据上文谁问谁、问的是什么来判断' }],
      explain: '补主语要看动作是谁做的，往前文找。对话中省略主语的情况很常见。' }
  ]
},

/* ================= 文言句式（二）：倒装句与被动句 ================= */
{
  id: 'w-jushi2', title: '文言句式（二）：倒装句与被动句', short: '倒装·被动句', module: 'wenyan', grade: 8, freq: 3,
  prereqs: ['w-jushi1'],
  tip: '倒装句是翻译题最常设的得分点，不调整语序就会被扣分；被动句要译出“被”。中考也常考“与例句句式相同”的选择题。',
  learn: [
    { h: '倒装句：古今语序不一样', html: `
      <p>现代汉语的基本语序是“主语—谓语—宾语”，修饰语在中心词前面。文言文里有些成分<b>位置跑了</b>，翻译时要<b>调回来</b>。</p>
      <p class="ex">何陋之有？（《陋室铭》）<span class="zh">＝有何陋：有什么简陋的呢？</span></p>
      <p>常见的倒装有四种：<b>宾语前置、定语后置、状语后置、主谓倒装</b>。</p>` },
    { h: '四种倒装', html: `
      <table class="tbl">
        <tr><th>类型</th><th>例句（出处）</th><th>正常语序 / 翻译</th></tr>
        <tr><td rowspan="5"><b>宾语前置</b></td><td>何以战（《曹刿论战》）</td><td>以何战：凭什么作战</td></tr>
        <tr><td>微斯人，吾谁与归（《岳阳楼记》）</td><td>吾与谁归：我和谁一道呢</td></tr>
        <tr><td>何陋之有（《陋室铭》）</td><td>有何陋：有什么简陋的呢</td></tr>
        <tr><td>莲之爱（《爱莲说》）</td><td>爱莲：对莲花的喜爱</td></tr>
        <tr><td>弗之怠（《送东阳马生序》）</td><td>弗怠之：不懈怠（抄书）</td></tr>
        <tr><td><b>定语后置</b></td><td>马之千里者（《马说》）</td><td>千里之马：能日行千里的马</td></tr>
        <tr><td rowspan="3"><b>状语后置</b><br>（介词短语后置）</td><td>战于长勺（《曹刿论战》）</td><td>于长勺战：在长勺作战</td></tr>
        <tr><td>屠惧，投以骨（《狼》）</td><td>以骨投之：把骨头扔给狼</td></tr>
        <tr><td>相与步于中庭（《记承天寺夜游》）</td><td>于中庭步：在庭院里散步</td></tr>
        <tr><td rowspan="2"><b>主谓倒装</b></td><td>甚矣，汝之不惠（《愚公移山》）</td><td>汝之不惠甚矣：你太不聪明了</td></tr>
        <tr><td>贤哉，回也（《论语》十二章）</td><td>回也贤哉：颜回真是贤德啊</td></tr>
      </table>` },
    { h: '宾语前置的三个信号', html: `
      <ol>
        <li><b>疑问句</b>里，疑问代词（何、谁、焉、安）作宾语，放在动词或介词前面：何以战、吾谁与归。</li>
        <li><b>否定句</b>里，代词作宾语，放在动词前面：弗之怠（不懈怠它）。</li>
        <li>用<b>“之”“是”</b>把宾语提前：何陋之有、莲之爱。</li>
      </ol>
      <p class="warn">易错：“何以战”不能译成“为什么作战”。“何以”＝“以何”，是“凭什么”。</p>` },
    { h: '被动句：主语是“受害者”', html: `
      <p>主语不是动作的发出者，而是<b>承受者</b>，就是被动句。</p>
      <table class="tbl">
        <tr><th>标志</th><th>例句（出处）</th><th>翻译</th></tr>
        <tr><td>为</td><td>兔不可复得，而身为宋国笑（《守株待兔》，选自《韩非子·五蠹》）</td><td>他自己被宋国人嘲笑</td></tr>
        <tr><td>为……所</td><td>常见格式，如“为人所笑”</td><td>被别人嘲笑</td></tr>
        <tr><td>见</td><td>吾长见笑于大方之家（《庄子·秋水》，成语“贻笑大方”由此而来）</td><td>我将长久地被懂得大道理的人笑话</td></tr>
        <tr><td>无标志（意念被动）</td><td>舜发于畎亩之中，傅说举于版筑之间（《生于忧患，死于安乐》）</td><td>舜从田野之中被起用，傅说从筑墙的工作中被选拔</td></tr>
      </table>
      <p class="warn">没有标志的被动句最容易漏掉。判断方法：主语能自己做这个动作吗？舜不能自己“起用”自己，所以“发”要译成“被起用”。</p>
      <div class="rhyme">疑问否定宾提前，<br>“之”“是”标志也常见；<br>定语后置“之……者”，<br>介宾短语往前搬；<br>主谓倒装为强调，<br>为、见、所、被要译全。</div>` }
  ],
  examples: [
    { type: 'choice', q: '下列句子中，属于<b>宾语前置</b>的一项是：', options: ['何以战', '马之千里者', '战于长勺', '甚矣，汝之不惠'], answer: 0,
      explain: '“何以战”＝“以何战”，疑问代词“何”作介词“以”的宾语，前置。“马之千里者”是定语后置，“战于长勺”是状语后置，“甚矣，汝之不惠”是主谓倒装。' },
    { type: 'open', q: '翻译：“微斯人，吾谁与归？”（《岳阳楼记》）',
      ref: '<p>如果没有这种人，我和谁一道呢？</p>',
      points: [{ s: 1, p: '“微”译为“（如果）没有”，“斯人”译为“这种人”' }, { s: 1, p: '“吾谁与归”按宾语前置调为“吾与谁归”，译为“我和谁一道（同归）呢”' }],
      explain: '疑问代词“谁”作介词“与”的宾语，放在了“与”前面。' },
    { type: 'choice', q: '《曹刿论战》中曹刿问鲁庄公：“何以战？”有同学译成“为什么作战”。下列判断正确的是：', options: [
        '译错了。“何以”＝“以何”，是“凭什么”，应译为“凭什么作战”',
        '译对了。“何以”就是“为什么”',
        '译错了。应译为“用什么方法逃跑”',
        '译错了。应译为“什么时候作战”'], answer: 0,
      explain: '这是宾语前置的易错点：疑问代词“何”作介词“以”的宾语，提到了“以”前面。“以何战”是“凭什么作战”。下文鲁庄公回答的“衣食所安”“牺牲玉帛”“小大之狱”都是作战的凭借。' },
    { type: 'open', q: '翻译：“天大寒，砚冰坚，手指不可屈伸，弗之怠。”（《送东阳马生序》）',
      ref: '<p>天气特别寒冷，砚台里的墨汁结成坚冰，手指（冻得）不能弯曲和伸直，（我）也不放松（抄书）。</p>',
      points: [{ s: 1, p: '“弗之怠”按宾语前置调为“弗怠之”，译为“不懈怠（抄书）”' }, { s: 1, p: '“砚冰坚”译为“砚台里的墨汁结成坚冰”，“屈伸”译为“弯曲和伸直”，句意通顺' }],
      explain: '否定句中（有“弗”），代词“之”作宾语，放到了动词“怠”的前面。' },
    { type: 'choice', q: '“<span class="dot-em">莲之爱</span>，同予者何人？”（《爱莲说》）中，“莲之爱”的正常语序和意思是：', options: [
        '爱莲：对莲花的喜爱',
        '莲爱：莲花的爱好',
        '莲的爱：莲花爱什么',
        '之爱莲：去爱莲花'], answer: 0,
      explain: '“莲”是“爱”的宾语，借助“之”提到了“爱”的前面，“之”是宾语前置的标志，不译。' },
    { type: 'choice', q: '“马之千里者，一食或尽粟一石。”中“马之千里者”的句式和正常语序，正确的一项是：', options: [
        '定语后置；千里之马',
        '宾语前置；千里马之',
        '状语后置；马于千里',
        '判断句；马是千里'], answer: 0,
      explain: '中心词“马”在前，修饰它的定语“千里”被放到了后面，用“之……者”作标志。正常语序是“千里之马”，即能日行千里的马。' },
    { type: 'open', q: '翻译：“怀民亦未寝，相与步于中庭。”（《记承天寺夜游》）',
      ref: '<p>张怀民也没有睡，（我们）一起在庭院中散步。</p>',
      points: [{ s: 1, p: '“步于中庭”按状语后置调为“于中庭步”，译为“在庭院中散步”' }, { s: 1, p: '“相与”译为“共同、一起”，“寝”译为“睡”，句意通顺' }],
      explain: '介词短语“于中庭”放在动词“步”后面，翻译时要提到动词前面。' },
    { type: 'open', q: '翻译：“贤哉，回也！”（《论语》十二章）（2 分）',
      ref: '<p>颜回真是贤德啊！</p>',
      points: [{ s: 1, p: '调整主谓倒装语序：回也贤哉' }, { s: 1, p: '“贤”译为“贤德”，“哉”译出感叹语气' }],
      explain: '谓语“贤哉”被提到主语“回也”前面，强调赞叹之情。翻译时要把主语放回前面。' },
    { type: 'choice', q: '“兔不可复得，而身<span class="dot-em">为</span>宋国笑”和“为人所笑”都是被动句。下列说法正确的一项是：', options: [
        '“为”和“为……所”都可以表示被动，译为“被”',
        '“为”只能表示“成为”，不能表被动',
        '“为……所”表示“为了……所以”',
        '被动句一定要有“被”字'], answer: 0,
      explain: '“身为宋国笑”是自己被宋国人嘲笑；“为人所笑”是被别人嘲笑。“为”“为……所”都是被动标志，翻译时都要译出“被”。' },
    { type: 'choice', q: '“吾长<span class="dot-em">见</span>笑于大方之家。”（《庄子·秋水》）中“见”的意思是：', options: ['被', '看见', '通“现”，出现', '见解'], answer: 0,
      explain: '我将长久地被懂得大道理的人笑话，“见”表被动，译为“被”，“于”引出动作的发出者。成语“贻笑大方”就来自这里。' },
    { type: 'open', q: '翻译：“舜发于畎亩之中，傅说举于版筑之间。”（《生于忧患，死于安乐》）（3 分）',
      ref: '<p>舜从田野之中被起用，傅说从筑墙的工作中被选拔出来。</p>',
      points: [{ s: 1, p: '“发”译出被动：被起用' }, { s: 1, p: '“举”译出被动：被选拔' }, { s: 1, p: '两个“于”译为“从”，并把介词短语提到动词前' }],
      explain: '这两句没有被动标志，是意念被动：舜、傅说不能自己起用、选拔自己，所以要译成“被起用”“被选拔”。' }
  ],
  tests: [
    { type: 'choice', q: '“微斯人，吾谁与归”中“吾谁与归”的正常语序是：', options: ['吾与谁归', '谁与吾归', '吾归与谁', '与吾谁归'], answer: 0,
      explain: '“谁”是介词“与”的宾语，前置了。正常语序是“吾与谁归”：我和谁一道呢。' },
    { type: 'choice', q: '下列句子中，属于<b>被动句</b>的一项是：', options: ['傅说举于版筑之间', '战于长勺', '何陋之有', '贤哉，回也'], answer: 0,
      explain: '“傅说举于版筑之间”是傅说从筑墙的工作中被选拔出来，没有被动标志，属于意念被动。“战于长勺”是状语后置，“何陋之有”是宾语前置，“贤哉，回也”是主谓倒装。' },
    { type: 'choice', q: '“天大寒，砚冰坚，手指不可屈伸，弗之怠”（《送东阳马生序》）中，“弗之怠”的正常语序和意思是：', options: [
        '弗怠之：不懈怠（抄书）',
        '之弗怠：他不懈怠',
        '怠弗之：懒惰而不去',
        '弗之怠：不到懒惰的地步'], answer: 0,
      explain: '否定句中代词“之”作宾语，放在动词“怠”前。“之”代抄书这件事。' },
    { type: 'choice', q: '“甚矣，汝之不惠！”（《愚公移山》）的句式是：', options: ['主谓倒装', '宾语前置', '定语后置', '被动句'], answer: 0,
      explain: '正常语序是“汝之不惠甚矣”，把谓语“甚矣”提到前面，强调智叟对愚公的嘲笑。' },
    { type: 'fill', q: '“屠惧，投以骨”（《狼》）中“投以骨”的正常语序是：（写原文的字）', answer: ['以骨投之', '以骨投', '以骨投狼'],
      explain: '这是状语后置（介词短语后置），正常语序是“以骨投之”：把骨头扔给狼。' },
    { type: 'choice', q: '“兔不可复得，而身<span class="dot-em">为</span>宋国笑”（《守株待兔》，选自《韩非子·五蠹》）中，“为”的意思是：', options: ['被', '成为', '为了', '是'], answer: 0,
      explain: '“为宋国笑”是“被宋国人嘲笑”，“为”表被动。' },
    { type: 'choice', q: '下列句子中，句式与“战于长勺”<b>相同</b>的一项是：', options: ['相与步于中庭', '何以战', '马之千里者', '甚矣，汝之不惠'], answer: 0,
      explain: '“战于长勺”“相与步于中庭”都是状语后置（介词短语“于……”放在动词后面）。“何以战”是宾语前置，“马之千里者”是定语后置，“甚矣，汝之不惠”是主谓倒装。' },
    { type: 'choice', q: '“何以战”的正常语序是：', options: ['以何战', '战以何', '何战以', '以战何'], answer: 0,
      explain: '疑问句中疑问代词“何”作介词“以”的宾语，前置了。正常语序是“以何战”：凭什么作战。' },
    { type: 'open', q: '翻译：“乃入见。问：‘何以战？’”（《曹刿论战》）并说明翻译时要注意什么。（2 分）',
      ref: '<p>翻译：（曹刿）于是入朝拜见（鲁庄公）。（曹刿）问：“凭借什么作战？”</p><p>注意：“何以”是宾语前置，即“以何”，要译为“凭什么”，不能译成“为什么”。</p>',
      points: [{ s: 1, p: '译为“凭借什么作战”（“凭什么作战”也可）' }, { s: 1, p: '说明“何以”是宾语前置（以何），不能译成“为什么”' }] },
    { type: 'fill', q: '写出“弗之怠”的正常语序：', answer: ['弗怠之', '不怠之'],
      explain: '否定句中代词“之”作宾语，前置到动词“怠”前。正常语序是“弗怠之”。' },
    { type: 'fill', q: '写出“何陋之有”的正常语序：', answer: ['有何陋'],
      explain: '“何陋”是“有”的宾语，用“之”作标志提到了前面。正常语序是“有何陋”。' },
    { type: 'choice', q: '“莲之爱，同予者何人”中，“莲之爱”的句式是：', options: ['宾语前置', '定语后置', '状语后置', '被动句'], answer: 0,
      explain: '“莲之爱”即“爱莲”，宾语“莲”借助“之”前置。' },
    { type: 'fill', q: '写出“马之千里者”的正常语序：', answer: ['千里之马', '千里马', '千里的马'],
      explain: '这是定语后置句，正常语序是“千里之马”。' },
    { type: 'choice', q: '下列句子中，属于<b>定语后置</b>的一项是：', options: ['马之千里者', '弗之怠', '投以骨', '甚矣，汝之不惠'], answer: 0,
      explain: '“马之千里者”用“之……者”把定语“千里”放在中心词“马”后面。“弗之怠”是宾语前置，“投以骨”是状语后置，“甚矣，汝之不惠”是主谓倒装。' },
    { type: 'choice', q: '“苟全性命于乱世”的句式是：', options: ['状语后置（介词短语后置）', '宾语前置', '定语后置', '被动句'], answer: 0,
      explain: '介词短语“于乱世”放在动词“苟全”后面，是状语后置，翻译时提前：在乱世中苟全性命。' },
    { type: 'choice', q: '“贤哉，回也！”的正常语序是：', options: ['回也贤哉', '贤回也哉', '哉贤回也', '也回贤哉'], answer: 0,
      explain: '这是主谓倒装，谓语“贤哉”提前以强调赞叹。正常语序是“回也贤哉”。' },
    { type: 'fill', q: '解释加点词：兔不可复得，而身<span class="dot-em">为</span>宋国笑。', answer: ['被'],
      explain: '“为”表被动，“身为宋国笑”是自己被宋国人嘲笑。' },
    { type: 'choice', q: '下列短语中，表示被动的一项是：', options: ['为人所笑', '为人谋', '为师', '为业'], answer: 0,
      explain: '“为……所……”是被动格式，“为人所笑”是被别人嘲笑。“为人谋”是替别人谋划，“为师”是做老师，“为业”是作为职业。' },
    { type: 'choice', q: '“不为外物所动”这类“为……所……”结构的正确理解是：', options: [
        '不被外界的事物所打动',
        '不为了外界的事物而行动',
        '不成为外界事物的动力',
        '不替外界事物去行动'], answer: 0,
      explain: '“为……所……”表被动，“为”引出动作的发出者（外物），“所”放在动词（动）前，整体译为“被……所……”。' },
    { type: 'fill', q: '解释加点词：吾长<span class="dot-em">见</span>笑于大方之家。（《庄子·秋水》）', answer: ['被'],
      explain: '“见”表被动，“见笑于大方之家”是被懂得大道理的人笑话。' },
    { type: 'choice', q: '下列句子中，加点“见”表示<b>被动</b>的一项是：', options: [
        '吾长<span class="dot-em">见</span>笑于大方之家',
        '才美不外<span class="dot-em">见</span>',
        '<span class="dot-em">见</span>渔人，乃大惊',
        '<span class="dot-em">见</span>其发矢十中八九'], answer: 0,
      explain: '“见笑于大方之家”是被人笑话，“见”表被动。“才美不外见”的“见”通“现”；“见渔人”“见其发矢”的“见”是看见。' },
    { type: 'choice', q: '“舜发于畎亩之中”中“发”的正确翻译是：', options: ['被起用', '出发', '发射', '起用（别人）'], answer: 0,
      explain: '舜不能自己起用自己，这是没有标志的意念被动，“发”要译为“被起用”。' },
    { type: 'choice', q: '下列对句式的判断，<b>有误</b>的一项是：', options: [
        '投以骨——被动句',
        '何以战——宾语前置',
        '马之千里者——定语后置',
        '傅说举于版筑之间——被动句（意念被动）'], answer: 0,
      explain: '“投以骨”是“以骨投之”，介词短语“以骨”后置，是状语后置句，不是被动句。' }
  ]
},

/* ================= 文言断句 ================= */
{
  id: 'w-duanju', title: '文言断句', short: '文言断句', module: 'wenyan', grade: 8, freq: 2,
  prereqs: ['w-jushi1'],
  tip: '中考常考“用‘/’给句子断句”或“朗读停顿正确的一项”。断句的前提是读懂意思，再借助虚词、对话标志和对称句式来判断。',
  learn: [
    { h: '断句是什么', html: `
      <p>古书原来没有标点符号，读书人要自己判断哪里该停顿，这叫“<b>句读</b>”（读 dòu）。考试中的断句题一般有两种：</p>
      <ol>
        <li><b>句间断句</b>：给一段没有标点的文字，用“/”断开句子。</li>
        <li><b>句中停顿</b>：给一个句子，选出朗读节奏正确的一项（主谓之间、动宾之间、句首发语词后常停顿）。</li>
      </ol>
      <p class="ex">山不在高/有仙则名/水不在深/有龙则灵（《陋室铭》）<span class="zh">山不在于高，有了仙人就出名；水不在于深，有了龙就显得有灵气。</span></p>` },
    { h: '五个断句信号', html: `
      <table class="tbl">
        <tr><th>信号</th><th>说明</th><th>例子</th></tr>
        <tr><td><b>名词、代词</b></td><td>常作主语，多在句首，前面可断</td><td>屠惧/投以骨（主语“屠”）</td></tr>
        <tr><td><b>句首词</b></td><td>夫、盖、若夫、且、至若等常在句首，前面断</td><td>……/盖竹柏影也</td></tr>
        <tr><td><b>句末语气词</b></td><td>也、矣、乎、哉、焉、耳、邪等，后面断</td><td>传不习乎/</td></tr>
        <tr><td><b>对话标志</b></td><td>曰、云、言等，后面常断</td><td>答曰/待君久不至</td></tr>
        <tr><td><b>对称句式</b></td><td>结构相同、字数相等的句子，一组组断</td><td>不以物喜/不以己悲</td></tr>
      </table>
      <p class="warn">“而”“则”“以”“于”大多在句中起连接作用，一般<b>不在它们后面断</b>：“学而不思则罔”中间不断开。</p>` },
    { h: '三步法 + 一个陷阱', html: `
      <ol>
        <li><b>通读</b>：先大致读懂说了什么事、有几个人。</li>
        <li><b>先易后难</b>：先断有把握的地方（曰、也、乎、对称句），再处理剩下的。</li>
        <li><b>回读检查</b>：断完后每一段意思都要完整，不能把一个词拆开。</li>
      </ol>
      <p><b>经典陷阱</b>：《爱莲说》“予谓菊花之隐逸者也”——如果断成“予谓菊花/之隐逸者也”就错了。原句是“予谓菊，花之隐逸者也”：菊花是花中的隐士。“菊”和“花”要分开！</p>
      <p><b>句中停顿</b>也不能破坏词语和意思：“其一犬坐于前”应读“其一/犬坐于前”（“其一”是其中一只，“犬坐”是像狗一样坐着），不能读成“其一犬/坐于前”。</p>
      <div class="rhyme">先读懂，再动手，<br>名词代词常在首；<br>夫盖若夫开头断，<br>也矣乎哉句尾留；<br>曰云之后多停顿，<br>对称句子成对走。</div>` }
  ],
  examples: [
    { type: 'choice', q: '用“/”给下面的句子断句，正确的一项是：<div class="passage"><p class="noindent">予谓菊花之隐逸者也牡丹花之富贵者也（《爱莲说》）</p></div>', options: [
        '予谓菊/花之隐逸者也/牡丹/花之富贵者也',
        '予谓菊花/之隐逸者也/牡丹花/之富贵者也',
        '予谓/菊花之隐逸/者也牡丹/花之富贵者也',
        '予谓菊花之/隐逸者也牡丹/花之富/贵者也'], answer: 0,
      explain: '原文是“予谓菊，花之隐逸者也；牡丹，花之富贵者也”：我认为菊花是花中的隐士，牡丹是花中的富贵者。“花之隐逸者”是一个整体，“菊”与“花”之间必须断开。' },
    { type: 'open', q: '用“/”给下面的句子断句（断两处）：<div class="passage"><p class="noindent">孤岂欲卿治经为博士邪但当涉猎见往事耳（《孙权劝学》）</p></div>',
      ref: '<p>孤岂欲卿治经为博士邪/但当涉猎/见往事耳</p>',
      points: [{ s: 1, p: '在句末语气词“邪”后断开' }, { s: 1, p: '在“涉猎”后断开（“但当涉猎”“见往事耳”各自成句）' }],
      explain: '“邪”是句末语气词，后面要断；“但当涉猎，见往事耳”意思是“只是应当粗略地阅读，了解历史罢了”，“涉猎”和“见往事”是两件事。' },
    { type: 'choice', q: '用“/”给下面的句子断句，正确的一项是：<div class="passage"><p class="noindent">庭下如积水空明水中藻荇交横盖竹柏影也（《记承天寺夜游》）</p></div>', options: [
        '庭下如积水空明/水中藻荇交横/盖竹柏影也',
        '庭下如积水/空明水中/藻荇交横盖/竹柏影也',
        '庭下如积/水空明水中藻荇/交横盖竹柏/影也',
        '庭下/如积水空明水中/藻荇交横盖竹/柏影也'], answer: 0,
      explain: '“盖”是常见的句首词（课本注：大概是），前面要断开；“水中藻荇交横”以名词“水中”开头，前面也要断。意思是：庭院中的月光像积水一样清澈透明，水中好像有藻、荇交错纵横，大概是竹子和柏树的影子。' },
    { type: 'choice', q: '用“/”给下面的句子断句，正确的一项是：<div class="passage"><p class="noindent">学而不思则罔思而不学则殆（《论语》十二章）</p></div>', options: [
        '学而不思则罔/思而不学则殆',
        '学而/不思则罔/思而/不学则殆',
        '学而不思/则罔思/而不学则殆',
        '学/而不思则罔思/而不学/则殆'], answer: 0,
      explain: '“而”“则”在句中起连接作用，一般不在它们前后断开。两句是对称句式，各六个字，在“罔”后断开。' },
    { type: 'choice', q: '下列句子朗读停顿划分<b>正确</b>的一项是：', options: [
        '醉翁之意/不在酒',
        '醉翁/之意不在酒',
        '醉/翁之意不在酒',
        '醉翁之意不/在酒'], answer: 0,
      explain: '“醉翁之意”（醉翁的情趣）是主语，“不在酒”是谓语，主谓之间停顿。“醉翁之意”是一个整体，不能从中间断开，“不在”也不能拆开。' },
    { type: 'open', q: '用“/”给下面这段话断句（断四处），并说说你是按什么步骤断的。<div class="passage"><p class="noindent">陈太丘与友期行期日中过中不至太丘舍去去后乃至（《陈太丘与友期行》）</p></div>',
      ref: '<p>陈太丘与友期行/期日中/过中不至/太丘舍去/去后乃至</p><p>步骤：先通读，读懂是“约好出发、朋友没来、太丘先走、朋友后到”这件事；再先易后难，在新的主语“太丘”前、时间词“过中”前、“去后”前断开；最后回读检查，每一段意思完整，没有拆开词语。</p>',
      points: [{ s: 1, p: '在“行”“中”（期日中）后断开' }, { s: 1, p: '在“至”（过中不至）、“去”（太丘舍去）后断开' }, { s: 1, p: '说出步骤：通读读懂—先断有把握的地方—回读检查' }],
      explain: '断句的前提是读懂意思。“期日中”是约定在正午，“过中不至”是过了正午没到，主语都可以从上下文推出来。' },
    { type: 'choice', q: '用“/”给下面的句子断句，正确的一项是：<div class="passage"><p class="noindent">答曰待君久不至已去（《陈太丘与友期行》）</p></div>', options: [
        '答曰/待君久不至/已去',
        '答/曰待君/久不至已去',
        '答曰待/君久不至/已去',
        '答曰待君久/不至已/去'], answer: 0,
      explain: '“曰”是对话标志，后面常断开；“待君久不至”（等您很久您都没到）和“已去”（已经离开了）是两层意思。' }
  ],
  tests: [
    { type: 'choice', q: '用“/”给下面的句子断句，正确的一项是：<div class="passage"><p class="noindent">山不在高有仙则名水不在深有龙则灵</p></div>', options: [
        '山不在高/有仙则名/水不在深/有龙则灵',
        '山不/在高有仙/则名水/不在深有龙则灵',
        '山不在高有仙/则名水不在/深有龙则灵',
        '山不在/高有仙则名/水不在/深有龙则灵'], answer: 0,
      explain: '“山不在高，有仙则名”和“水不在深，有龙则灵”是对称句式，每四字一断。' },
    { type: 'choice', q: '用“/”给下面的句子断句，正确的一项是：<div class="passage"><p class="noindent">三人行必有我师焉择其善者而从之其不善者而改之</p></div>', options: [
        '三人行/必有我师焉/择其善者而从之/其不善者而改之',
        '三人/行必有我/师焉择其善者/而从之其不善者而改之',
        '三人行必有/我师焉择/其善者而从之其/不善者而改之',
        '三人行/必有我师/焉择其善者/而从之其不善者/而改之'], answer: 0,
      explain: '“焉”在句末（兼词，相当于“于此”），后面要断；“择其善者而从之”“其不善者而改之”是对称句，“而”在句中连接，不在它前后断开。' },
    { type: 'choice', q: '用“/”给下面的句子断句，正确的一项是：（遽：急忙；契：刻）<div class="passage"><p class="noindent">楚人有涉江者其剑自舟中坠于水遽契其舟曰是吾剑之所从坠</p></div>', options: [
        '楚人有涉江者/其剑自舟中坠于水/遽契其舟/曰/是吾剑之所从坠',
        '楚人有涉/江者其剑/自舟中坠于水/遽契其舟曰/是吾剑之所从坠',
        '楚人有涉江者其剑/自舟中坠/于水遽契/其舟曰是/吾剑之所从坠',
        '楚人/有涉江者其剑自舟中/坠于水遽/契其舟曰是吾剑/之所从坠'], answer: 0,
      explain: '“楚人有涉江者”交代人物；“其剑自舟中坠于水”是新的主语“其剑”开头；“遽契其舟”是动作；“曰”后是说的话。这段出自《吕氏春秋·察今》里的《刻舟求剑》。' },
    { type: 'choice', q: '用“/”给下面的句子断句，正确的一项是：<div class="passage"><p class="noindent">已得履乃曰吾忘持度反归取之</p></div>（出自《韩非子·外储说左上》的《郑人买履》。度：量好的尺码）', options: [
        '已得履/乃曰/吾忘持度/反归取之',
        '已得/履乃曰吾/忘持度反/归取之',
        '已得履乃/曰吾忘/持度反归/取之',
        '已/得履乃曰吾忘持/度反归取之'], answer: 0,
      explain: '拿到鞋以后，才说：“我忘记带尺码了。”于是返回家去取。“乃曰”后面是说的话，“吾”是说话内容的主语，前面断开。' },
    { type: 'choice', q: '下列句子朗读停顿划分<b>正确</b>的一项是：', options: [
        '其一/犬坐于前',
        '其/一犬坐于前',
        '其一犬/坐于前',
        '其一犬坐/于前'], answer: 0,
      explain: '“其一”是“其中一只（狼）”，是主语；“犬坐”是“像狗一样坐着”，是一个整体，不能拆开。' },
    { type: 'choice', q: '下列句子朗读停顿划分<b>正确</b>的一项是：', options: [
        '食马者/不知其能千里而食也',
        '食马/者不知其能千里而食也',
        '食马者不知其/能千里而食也',
        '食马者不知其能千里/而食也'], answer: 0,
      explain: '“食马者”（喂马的人）是主语，主语和谓语之间停顿。“者”和“食马”是一体，不能分开。' },
    { type: 'choice', q: '用“/”给下面的句子断句，正确的一项是：（据朱熹《三朝名臣言行录》，写司马光读书）<div class="passage"><p class="noindent">用力多者收功远其所精诵乃终身不忘也</p></div>', options: [
        '用力多者收功远/其所精诵/乃终身不忘也',
        '用力多者/收功远其所/精诵乃终身/不忘也',
        '用力/多者收功/远其所精诵乃/终身不忘也',
        '用力多者收功远其/所精诵乃终身/不忘也'], answer: 0,
      explain: '“用力多者收功远”：花的力气多，收获就长远；“其所精诵”：他精心背诵过的（内容）；“乃终身不忘也”：就一辈子都不会忘记。“其所精诵”是新的主语。' },
    { type: 'choice', q: '用“/”给下面的句子断句，正确的一项是：<div class="passage"><p class="noindent">若夫日出而林霏开云归而岩穴暝（《醉翁亭记》）</p></div>', options: [
        '若夫日出而林霏开/云归而岩穴暝',
        '若夫/日出而/林霏开云归/而岩穴暝',
        '若夫日出/而林霏开云/归而岩穴暝',
        '若/夫日出而林霏/开云归而岩穴暝'], answer: 0,
      explain: '“若夫”是句首词，放在一句的开头；“日出而林霏开”和“云归而岩穴暝”结构对称，“而”在句中不断开。' },
    { type: 'choice', q: '下列各句中，断句<b>正确</b>的一项是：', options: [
        '水中藻荇交横/盖竹柏影也',
        '水中藻荇交横盖/竹柏影也',
        '水中藻荇/交横盖竹柏/影也',
        '水中/藻荇交横盖竹/柏影也'], answer: 0,
      explain: '“盖”是句首词，课本注释是“大概是”，前面断开。“竹柏”是竹子和柏树，不能拆开。' },
    { type: 'choice', q: '用“/”给下面的句子断句，正确的一项是：<div class="passage"><p class="noindent">吾日三省吾身为人谋而不忠乎与朋友交而不信乎传不习乎</p></div>', options: [
        '吾日三省吾身/为人谋而不忠乎/与朋友交而不信乎/传不习乎',
        '吾日三省/吾身为人谋/而不忠乎与朋友交/而不信乎传不习乎',
        '吾日/三省吾身为人/谋而不忠乎与/朋友交而不信乎传/不习乎',
        '吾日三省吾身为人谋/而不忠乎/与朋友交而不信/乎传不习乎'], answer: 0,
      explain: '三个“乎”都是句末语气词，后面断开；三个问句结构对称。“吾日三省吾身”是总说。' },
    { type: 'choice', q: '用“/”给下面的句子断句，正确的一项是：<div class="passage"><p class="noindent">士别三日即更刮目相待大兄何见事之晚乎（《孙权劝学》）</p></div>', options: [
        '士别三日/即更刮目相待/大兄何见事之晚乎',
        '士别/三日即更/刮目相待大兄/何见事之晚乎',
        '士别三日即/更刮目相待大/兄何见事之晚乎',
        '士别三日即更刮目/相待大兄何见/事之晚乎'], answer: 0,
      explain: '“大兄”是称呼，作新句子的主语，前面断开；“乎”是句末语气词，后面断开。“刮目相待”是一个整体，不能拆开。' },
    { type: 'choice', q: '用“/”给下面的句子断句，正确的一项是：<div class="passage"><p class="noindent">客问元方尊君在不答曰待君久不至已去</p></div>', options: [
        '客问元方/尊君在不/答曰/待君久不至/已去',
        '客问/元方尊君/在不答曰待/君久不至已去',
        '客问元方尊/君在不答/曰待君久/不至已去',
        '客问元方尊君/在不/答曰待君/久不至已去'], answer: 0,
      explain: '“问”“曰”后面是说的话，常要断开；“尊君在不”中的“不”通“否”，是句末语气，后面断开。' },
    { type: 'choice', q: '用“/”给下面的句子断句，正确的一项是：<div class="passage"><p class="noindent">居庙堂之高则忧其民处江湖之远则忧其君（《岳阳楼记》）</p></div>', options: [
        '居庙堂之高则忧其民/处江湖之远则忧其君',
        '居庙堂之高/则忧其民处/江湖之远/则忧其君',
        '居庙堂/之高则忧其民处江湖/之远则忧其君',
        '居庙堂之高则/忧其民处江湖之远则/忧其君'], answer: 0,
      explain: '两句结构完全对称：“居……之高则忧其……”“处……之远则忧其……”，一组一组地断。“则”在句中连接，后面一般不断。' },
    { type: 'choice', q: '下列断句中，<b>错误</b>的一项是：', options: [
        '学而/不思则罔',
        '不以物喜/不以己悲',
        '山不在高/有仙则名',
        '择其善者而从之/其不善者而改之'], answer: 0,
      explain: '“而”大多在句中起连接作用，一般不在它后面断开。“学而不思则罔”是一个完整的句子，中间不断。' },
    { type: 'choice', q: '关于文言断句的“三步法”，下列说法正确的一项是：', options: [
        '先通读读懂大意，再先易后难断有把握的地方，最后回读检查每段意思是否完整',
        '先把所有“之”字前后都断开，再读意思',
        '每四个字断一次，最后检查字数',
        '先断最难的地方，容易的地方最后再看'], answer: 0,
      explain: '断句的前提是读懂意思。先断“曰”“也”“乎”、对称句这些有把握的地方，最后回读，确保没有把一个词拆开。' },
    { type: 'choice', q: '断完句后“回读检查”，主要是检查：', options: [
        '每一段意思是否完整，有没有把一个词拆开',
        '每一段字数是否相等',
        '每一段是不是都以“也”结尾',
        '断的地方是不是越多越好'], answer: 0,
      explain: '回读时看每一段能不能讲通，有没有把“醉翁之意”“刮目相待”这样的整体拆开。' },
    { type: 'open', q: '有同学把《爱莲说》中“予谓菊花之隐逸者也”断成“予谓菊花/之隐逸者也”。请指出错误并改正。（2 分）',
      ref: '<p>错在把“菊”和“花”连在一起了。原文是“予谓菊，花之隐逸者也”，意思是“我认为菊花是花中的隐士”。“菊”是被判断的对象，“花之隐逸者”是一个整体，应断为“予谓菊/花之隐逸者也”。</p>',
      points: [{ s: 1, p: '指出错误：“菊”和“花”不能连读，“花之隐逸者”是一个整体' }, { s: 1, p: '改正：予谓菊/花之隐逸者也' }] },
    { type: 'choice', q: '用“/”给下面的句子断句，正确的一项是：<div class="passage"><p class="noindent">牡丹花之富贵者也莲花之君子者也</p></div>', options: [
        '牡丹/花之富贵者也/莲/花之君子者也',
        '牡丹花/之富贵者也/莲花/之君子者也',
        '牡丹花之/富贵者也莲/花之君子者也',
        '牡丹花之富贵/者也莲花之/君子者也'], answer: 0,
      explain: '和“菊，花之隐逸者也”一样：“牡丹，花之富贵者也；莲，花之君子者也。”“花之富贵者”“花之君子者”是整体，“牡丹”“莲”后断开。' },
    { type: 'choice', q: '下列句子朗读停顿划分<b>正确</b>的一项是：', options: [
        '陈胜者/阳城人也',
        '陈胜/者阳城人也',
        '陈胜者阳/城人也',
        '陈胜者阳城/人也'], answer: 0,
      explain: '“陈胜者”是主语，“者”和“陈胜”是一体，在“者”后停顿；“阳城”是地名，不能拆开。' }
  ]
},

/* ================= 文言内容理解与人物分析 ================= */
{
  id: 'w-neirong', title: '文言内容理解与人物分析', short: '内容理解', module: 'wenyan', grade: 8, freq: 3,
  prereqs: ['w-fanyi'],
  tip: '文言文阅读除了词句，还常考内容理解：概括事件、分析人物、说明原因、谈启示。答题要先读懂，再回原文找依据，观点加依据才能拿全分。',
  learn: [
    { h: '内容理解考什么', html: `
      <table class="tbl">
        <tr><th>题型</th><th>常见问法</th><th>答题要点</th></tr>
        <tr><td>内容理解选择题</td><td>下列对文章内容的理解，不正确的一项是</td><td>逐项回原文核对，找出与原文不符的地方</td></tr>
        <tr><td>信息筛选</td><td>文中哪些语句表现了……</td><td>直接摘录原句，或用自己的话概括</td></tr>
        <tr><td>人物形象</td><td>××是个怎样的人？结合文章分析</td><td>品质词＋依据（言行、事件）</td></tr>
        <tr><td>原因分析</td><td>××为什么……？</td><td>在前文找事件，按因果关系作答</td></tr>
        <tr><td>道理、启示</td><td>这个故事告诉我们什么道理？</td><td>从结局和人物言行反推，写成一句完整的话</td></tr>
      </table>` },
    { h: '第一步：先读懂，再回原文', html: `
      <p>内容题的基础是<b>翻译</b>。读文章时边读边在心里译，读完要能用一两句话说出“谁，做了什么，结果怎样”。</p>
      <p>以《卖油翁》为例：</p>
      <p class="ex">陈康肃公尧咨善射，当世无双，公亦以此自矜。<span class="zh">康肃公陈尧咨擅长射箭，当时世上没有第二个人能和他相比，他也凭着这种本领自夸。</span></p>
      <p>一句话概括：<b>卖油翁用倒油的本领，向自夸善射的陈尧咨说明了“熟能生巧”的道理。</b></p>
      <p>答题时，每个说法都要能在原文中找到<b>对应的句子</b>。比如说卖油翁技艺高超，依据就是“自钱孔入，而钱不湿”。</p>` },
    { h: '人物分析：品质词＋依据', html: `
      <p>分析人物，要做到“<b>有观点，有依据</b>”。答题模板：</p>
      <div class="tipbox">从“______”（原文语句或事件）可以看出，他是一个______的人。</div>
      <table class="tbl">
        <tr><th>人物（出处）</th><th>依据</th><th>品质</th></tr>
        <tr><td>卖油翁（《卖油翁》）</td><td>“无他，但手熟尔”；酌油时“自钱孔入，而钱不湿”</td><td>技艺纯熟，谦虚，不卑不亢</td></tr>
        <tr><td>陈尧咨（《卖油翁》）</td><td>“公亦以此自矜”；“尔安敢轻吾射”；最后“笑而遣之”</td><td>骄傲自负，但能接受事实</td></tr>
        <tr><td>元方（《陈太丘与友期行》）</td><td>“日中不至，则是无信；对子骂父，则是无礼”</td><td>聪明，明白事理，能维护父亲的尊严</td></tr>
        <tr><td>吕蒙（《孙权劝学》）</td><td>“蒙乃始就学”，后来令鲁肃“大惊”</td><td>知错能改，虚心好学</td></tr>
      </table>
      <p class="warn">人物分析要看<b>全篇</b>：陈尧咨开始骄傲，最后“笑而遣之”，说明他也能接受别人的道理。只说一面会丢分。</p>` },
    { h: '选择题的五个陷阱', html: `
      <table class="tbl">
        <tr><th>陷阱</th><th>表现</th><th>例子（《桃花源记》）</th></tr>
        <tr><td>张冠李戴</td><td>把甲做的事安到乙头上</td><td>说“渔人问村里人现在是什么朝代”（原文“问今是何世”是村里人问渔人）</td></tr>
        <tr><td>无中生有</td><td>原文没有的内容</td><td>说“渔人把桃花源的事告诉了全村人”</td></tr>
        <tr><td>曲解词义</td><td>按今义理解古词</td><td>把“率妻子邑人”理解为“带着妻子和乡亲”</td></tr>
        <tr><td>因果倒置、强加因果</td><td>把原因和结果说反或硬凑因果</td><td>说“刘子骥因为找不到桃花源而病死”（原文只是“未果，寻病终”）</td></tr>
        <tr><td>以偏概全、时间错位</td><td>部分说成全部，前后顺序弄乱</td><td>说“渔人一进山洞就看到了良田美池”（原文是“初极狭，才通人。复行数十步，豁然开朗”）</td></tr>
      </table>
      <div class="rhyme">先译后答心有底，<br>回到原文找依据；<br>人物品质加例证，<br>选项陷阱细对比。</div>` }
  ],
  passages: {
    chen: { title: '阅读下面的文言文，完成后面的题目。', html: `
      <p style="text-align:center;text-indent:0"><b>陈太丘与友期行</b></p>
      <p>陈太丘与友期行，期日中。过中不至，太丘舍去，去后乃至。元方时年七岁，门外戏。客问元方：“尊君在不？”答曰：“待君久不至，已去。”友人便怒曰：“非人哉！与人期行，相委而去。”元方曰：“君与家君期日中。日中不至，则是无信；对子骂父，则是无礼。”友人惭，下车引之。元方入门不顾。</p>
      <p class="noindent" style="font-size:14px">【注】期：约定。日中：正午。尊君：对别人父亲的尊称。家君：对人谦称自己的父亲。委：丢下。顾：回头看。</p>` },
    guan: { title: '阅读下面的文言文，完成后面的题目。', html: `
      <p style="text-align:center;text-indent:0"><b>管宁割席</b>（选自《世说新语·德行》）</p>
      <p>管宁、华歆共园中锄菜，见地有片金，管挥锄与瓦石不异，华捉而掷去之。又尝同席读书，有乘轩冕过门者，宁读如故，歆废书出看。宁割席分坐，曰：“子非吾友也。”</p>
      <p class="noindent" style="font-size:14px">【注】捉：拿起。轩冕：古代大夫以上的官员乘坐的车子和戴的礼帽，这里指达官显贵。席：坐席，古人铺在地上坐的席子。</p>` },
    maiyou: { title: '阅读下面的文言文，完成后面的题目。', html: `
      <p style="text-align:center;text-indent:0"><b>卖油翁</b>（欧阳修）</p>
      <p>陈康肃公尧咨善射，当世无双，公亦以此自矜。尝射于家圃，有卖油翁释担而立，睨之久而不去。见其发矢十中八九，但微颔之。</p>
      <p>康肃问曰：“汝亦知射乎？吾射不亦精乎？”翁曰：“无他，但手熟尔。”康肃忿然曰：“尔安敢轻吾射！”翁曰：“以我酌油知之。”乃取一葫芦置于地，以钱覆其口，徐以杓酌油沥之，自钱孔入，而钱不湿。因曰：“我亦无他，惟手熟尔。”康肃笑而遣之。</p>
      <p class="noindent" style="font-size:14px">【注】自矜：自夸。圃：园子。释：放下。睨：斜着眼看。颔：点头。忿然：气愤的样子。酌：舀取。沥：注入。遣：打发。</p>` },
    taoyuan: { title: '阅读下面的文言文，完成后面的题目。', html: `
      <p style="text-align:center;text-indent:0"><b>桃花源记</b>（陶渊明）</p>
      <p>晋太元中，武陵人捕鱼为业。缘溪行，忘路之远近。忽逢桃花林，夹岸数百步，中无杂树，芳草鲜美，落英缤纷。渔人甚异之。复前行，欲穷其林。</p>
      <p>林尽水源，便得一山，山有小口，仿佛若有光。便舍船，从口入。初极狭，才通人。复行数十步，豁然开朗。土地平旷，屋舍俨然，有良田、美池、桑竹之属。阡陌交通，鸡犬相闻。其中往来种作，男女衣着，悉如外人。黄发垂髫，并怡然自乐。</p>
      <p>见渔人，乃大惊，问所从来。具答之。便要还家，设酒杀鸡作食。村中闻有此人，咸来问讯。自云先世避秦时乱，率妻子邑人来此绝境，不复出焉。问今是何世，乃不知有汉，无论魏晋。此人一一为具言所闻，皆叹惋。余人各复延至其家，皆出酒食。停数日，辞去。此中人语云：“不足为外人道也。”</p>
      <p>既出，得其船，便扶向路，处处志之。及郡下，诣太守，说如此。太守即遣人随其往，寻向所志，遂迷，不复得路。</p>
      <p>南阳刘子骥，高尚士也，闻之，欣然规往。未果，寻病终。后遂无问津者。</p>
      <p class="noindent" style="font-size:14px">【注】黄发垂髫：指老人和小孩。要：通“邀”，邀请。妻子：妻子和儿女。绝境：与人世隔绝的地方。无论：不要说，更不必说。延：邀请。诣：拜访。规：计划。问津：探访，问路。</p>` }
  },
  examples: [
    { type: 'choice', q: '阅读《卖油翁》选段，对卖油翁形象的分析，最恰当的一项是：<div class="passage"><p>康肃问曰：“汝亦知射乎？吾射不亦精乎？”翁曰：“无他，但手熟尔。”康肃忿然曰：“尔安敢轻吾射！”翁曰：“以我酌油知之。”乃取一葫芦置于地，以钱覆其口，徐以杓酌油沥之，自钱孔入，而钱不湿。因曰：“我亦无他，惟手熟尔。”</p></div>', options: [
        '技艺纯熟，面对权贵不卑不亢，用事实讲道理',
        '胆小怕事，被陈尧咨一骂就赶紧表演倒油讨好他',
        '骄傲自大，故意卖弄倒油的本领来压倒陈尧咨',
        '看不起射箭，认为射箭比不上倒油'], answer: 0,
      explain: '面对陈尧咨的“忿然”，卖油翁没有害怕，也没有争吵，而是用“酌油”的事实证明“惟手熟尔”，说明他技艺纯熟、不卑不亢。他说“我亦无他”，态度谦虚，并不是卖弄；他也没有看不起射箭，只是说射箭也是“手熟”罢了。' },
    { type: 'open', q: '《狼》的结尾说：“狼亦黠矣，而顷刻两毙，禽兽之变诈几何哉？止增笑耳。”结合全文，说说这几句话表达了什么道理。',
      ref: '<p>狼虽然狡猾，但最终还是被屠户杀死了。这几句话告诉我们：像狼一样的恶势力不管多么狡猾奸诈，终究会失败；对待它们不能妥协退让，要敢于斗争、善于斗争。</p>',
      points: [{ s: 1, p: '概括事件：狡猾的狼最终被屠户杀死' }, { s: 1, p: '道理一：恶势力再狡诈也终将失败' }, { s: 1, p: '道理二：对待恶势力要敢于斗争、善于斗争，不能妥协' }],
      explain: '屠户开始“投以骨”，一味退让，狼却“并驱如故”；后来“奔倚其下，弛担持刀”，主动出击才转危为安。道理要结合情节来说。' },
    { type: 'open', q: '阅读《卖油翁》选段，找出表现卖油翁技艺高超的语句，并用自己的话概括。（2 分）<div class="passage"><p>翁曰：“以我酌油知之。”乃取一葫芦置于地，以钱覆其口，徐以杓酌油沥之，自钱孔入，而钱不湿。因曰：“我亦无他，惟手熟尔。”</p></div>',
      ref: '<p>语句：“乃取一葫芦置于地，以钱覆其口，徐以杓酌油沥之，自钱孔入，而钱不湿。”</p><p>概括：卖油翁用杓子把油从铜钱的方孔中倒进葫芦，油从钱孔流进去，铜钱却一点没沾湿，说明他倒油的技术极其纯熟。</p>',
      points: [{ s: 1, p: '摘录关键句：“自钱孔入，而钱不湿”（或整句）' }, { s: 1, p: '概括：油穿过钱孔而钱不湿，技艺纯熟' }],
      explain: '信息筛选题可以直接摘录原句，也可以用自己的话概括；最稳妥的做法是先摘句、再概括。“自钱孔入，而钱不湿”是最关键的一句。' },
    { type: 'open', q: '阅读《卖油翁》选段，回答：陈尧咨为什么“忿然”？（2 分）<div class="passage"><p>陈康肃公尧咨善射，当世无双，公亦以此自矜。……见其发矢十中八九，但微颔之。康肃问曰：“汝亦知射乎？吾射不亦精乎？”翁曰：“无他，但手熟尔。”康肃忿然曰：“尔安敢轻吾射！”</p></div>',
      ref: '<p>陈尧咨擅长射箭，并以此自夸；卖油翁看他射箭只是微微点头，还说他射箭“无他，但手熟尔”，没有什么奥妙，只不过手法熟练罢了。陈尧咨觉得卖油翁轻视自己的射箭本领，所以很生气。</p>',
      points: [{ s: 1, p: '陈尧咨善射而“自矜”（骄傲自负）' }, { s: 1, p: '卖油翁“但微颔之”，又说“但手熟尔”，他认为卖油翁轻视自己' }],
      explain: '原因分析题要先读懂，再在前文找事件，按因果关系作答：一方面是陈尧咨自己的性格，一方面是卖油翁的言行。' },
    { type: 'open', q: '结合《卖油翁》全文，说说陈尧咨是一个怎样的人。（3 分）<div class="passage"><p>陈康肃公尧咨善射，当世无双，公亦以此自矜。……康肃忿然曰：“尔安敢轻吾射！”……（卖油翁酌油后）康肃笑而遣之。</p></div>',
      ref: '<p>陈尧咨擅长射箭，“当世无双”，但他“以此自矜”，听到卖油翁说“但手熟尔”就“忿然”发问，说明他骄傲自负、心胸不够宽广；看了卖油翁酌油之后，他“笑而遣之”，说明他也能接受事实、明白道理。</p>',
      points: [{ s: 1, p: '善射：“善射，当世无双”' }, { s: 1, p: '骄傲自负：“以此自矜”“尔安敢轻吾射”' }, { s: 1, p: '能接受事实：结尾“笑而遣之”' }],
      explain: '人物分析要看全篇：只说陈尧咨骄傲，忽略了结尾的“笑而遣之”，就会丢分。' },
    { type: 'choice', q: '阅读《桃花源记》选段，下列理解<b>不正确</b>的一项是：<div class="passage"><p>见渔人，乃大惊，问所从来。具答之。便要还家，设酒杀鸡作食。村中闻有此人，咸来问讯。自云先世避秦时乱，率妻子邑人来此绝境，不复出焉。问今是何世，乃不知有汉，无论魏晋。</p></div>', options: [
        '渔人向村里人打听现在是什么朝代，村里人回答不知道有汉朝',
        '村里人见到渔人很吃惊，问他从哪里来',
        '村里人邀请渔人到家里，摆酒杀鸡款待他',
        '村里人的祖先为躲避秦时战乱，带着家人和同乡来到这里'], answer: 0,
      explain: '“问今是何世”是村里人问渔人现在是什么朝代，选项把提问的人弄反了，这是“张冠李戴”。做题时要逐项回原文找对应的句子，看清动作是谁做的。' },
    { type: 'choice', q: '阅读《桃花源记》结尾，下列理解<b>不正确</b>的一项是：<div class="passage"><p>南阳刘子骥，高尚士也，闻之，欣然规往。未果，寻病终。后遂无问津者。</p></div>', options: [
        '刘子骥因为找不到桃花源，忧愁成病而死',
        '刘子骥是一位志趣高尚的人',
        '刘子骥听说这件事后，高兴地计划前往',
        '刘子骥死后，就再也没有探访桃花源的人了'], answer: 0,
      explain: '原文只说“未果，寻病终”：计划没有实现，不久就病死了，并没有说他是因为找不到桃花源而病死，这是“强加因果”。' },
    { type: 'choice', q: '阅读《桃花源记》选段，下列理解<b>不正确</b>的一项是：<div class="passage"><p>林尽水源，便得一山，山有小口，仿佛若有光。便舍船，从口入。初极狭，才通人。复行数十步，豁然开朗。土地平旷，屋舍俨然，有良田、美池、桑竹之属。</p></div>', options: [
        '渔人一进山洞，就看到了平坦的土地和整齐的房屋',
        '桃花林在溪水的源头就到了尽头',
        '山洞一开始很窄，只能容一个人通过',
        '桃花源里有肥沃的田地、美丽的池塘和桑树竹子之类'], answer: 0,
      explain: '原文是“初极狭，才通人。复行数十步，豁然开朗”，渔人走了几十步才豁然开朗，不是一进洞就看到。这是“时间错位”，把先后顺序弄乱了。' },
    { type: 'choice', q: '下列对《桃花源记》内容的理解，<b>不正确</b>的一项是：<div class="passage"><p>自云先世避秦时乱，率妻子邑人来此绝境，不复出焉。……此人一一为具言所闻，皆叹惋。</p></div>', options: [
        '桃花源人的祖先带着妻子和同乡逃到这个走投无路的地方，再也出不去了',
        '桃花源人的祖先是为了躲避秦朝时的战乱才来到这里的',
        '渔人把自己知道的事一一详细地告诉了村里人',
        '村里人听了渔人的话，都感叹惋惜'], answer: 0,
      explain: '这个选项犯了“曲解词义”的错误：“妻子”是妻子和儿女，“绝境”是与人世隔绝的地方，“不复出”是不再出去（不是出不去）。按今义理解，意思就全错了。' },
    { type: 'choice', q: '读完《卖油翁》，用一句话概括全文内容，最恰当的一项是：', options: [
        '卖油翁用倒油的本领，向自夸善射的陈尧咨说明了“熟能生巧”的道理',
        '陈尧咨射箭十中八九，卖油翁非常佩服他',
        '卖油翁和陈尧咨比赛射箭，卖油翁赢了',
        '陈尧咨看不起卖油翁，把他赶走了'], answer: 0,
      explain: '内容题的基础是读懂全文，能用一两句话说出“谁，做了什么，结果怎样”。卖油翁只是“微颔之”，并不佩服；两人没有比赛射箭；“笑而遣之”是笑着打发他走，不是看不起后赶走。' },
    { type: 'choice', q: '下列对《卖油翁》的理解，<b>不正确</b>的一项是：<div class="passage"><p>见其发矢十中八九，但微颔之。</p></div>', options: [
        '卖油翁对陈尧咨的射技完全不认可，认为他射得很差',
        '陈尧咨射出的箭，十支能射中八九支',
        '卖油翁看到后只是微微点头',
        '“但微颔之”表现出卖油翁对陈尧咨射技略有赞许，但并不惊叹'], answer: 0,
      explain: '“微颔之”是微微点头，说明卖油翁有所肯定，只是不觉得有什么了不起。说他“完全不认可”是夸大其词、以偏概全。' }
  ],
  tests: [
    { type: 'choice', passage: 'chen', q: '下列对文章内容的理解，<b>不正确</b>的一项是：', options: [
        '陈太丘和朋友约定正午出发，朋友过了正午还没到，陈太丘就先走了',
        '友人得知陈太丘已经离开后，生气地骂他“非人哉”',
        '元方指出友人既“无信”又“无礼”，使友人感到惭愧',
        '友人下车拉元方表示歉意，元方原谅了他，陪他一起进了家门'], answer: 3,
      explain: '原文是“元方入门不顾”：元方走进家门，连头也不回。并没有陪友人进门。' },
    { type: 'fill', passage: 'chen', q: '解释加点词：友人惭，下车<span class="dot-em">引</span>之。', answer: ['拉', '牵', '拉他', '牵拉', '拉住'],
      explain: '友人感到惭愧，下车去拉元方，想表示亲近和歉意。“引”是“拉”。' },
    { type: 'open', passage: 'chen', q: '翻译：君与家君期日中。日中不至，则是无信；对子骂父，则是无礼。',
      ref: '<p>您和我父亲约定在正午出发。（您）正午没到，就是不讲信用；对着孩子骂他的父亲，就是没有礼貌。</p>',
      points: [{ s: 1, p: '“君”译为“您”，“家君”译为“我父亲”，“期日中”译为“约定在正午”' }, { s: 1, p: '“无信”译为“不讲信用”' }, { s: 1, p: '“对子骂父”译为“对着儿子骂他的父亲”，“无礼”译为“没有礼貌”' }] },
    { type: 'open', passage: 'chen', q: '元方是一个怎样的孩子？请结合文章内容简要分析。',
      ref: '<p>元方是一个聪明机智、明白事理的孩子。他抓住友人“日中不至”和“对子骂父”两点，指出友人“无信”“无礼”，说得有理有据，让友人感到惭愧；他还敢于维护父亲的尊严，面对大人的辱骂毫不退让。</p>',
      points: [{ s: 1, p: '品质：聪明机智、明白事理（能言善辩）' }, { s: 1, p: '依据：用“无信”“无礼”两点有理有据地反驳友人，使友人惭愧' }, { s: 1, p: '品质与依据：敢于维护父亲的尊严（面对友人骂父，毫不退让）' }] },
    { type: 'choice', passage: 'guan', q: '“宁读如故，歆<span class="dot-em">废</span>书出看”中，“废”的意思是：', options: ['放下', '废除', '荒废', '作废'], answer: 0,
      explain: '管宁照样读书，华歆却放下书跑出去看，“废”是“放下”。' },
    { type: 'choice', passage: 'guan', q: '下列对文章内容的理解，<b>不正确</b>的一项是：', options: [
        '看到地上的金片，管宁把它和瓦片石头同样看待，华歆则拿起来又扔掉了',
        '有达官显贵从门前经过，管宁照常读书，华歆放下书出去观看',
        '管宁割开坐席和华歆分开坐，表示不再把华歆当作朋友',
        '华歆把捡到的金片据为己有，管宁因此和他绝交'], answer: 3,
      explain: '原文是“华捉而掷去之”，华歆拿起金片后又扔掉了，并没有据为己有；管宁割席是在“歆废书出看”之后。这个选项无中生有。' },
    { type: 'open', passage: 'guan', q: '管宁为什么要和华歆“割席分坐”？请结合文中两件事说明。',
      ref: '<p>锄菜见金时，华歆“捉而掷去之”，说明他心里还是看重钱财的；读书时有达官显贵经过，华歆“废书出看”，说明他羡慕权势富贵，读书不专心。管宁认为华歆和自己志趣不同，所以割席分坐，不再和他做朋友。</p>',
      points: [{ s: 1, p: '事件一：见金时华歆“捉而掷去之”，说明他看重钱财' }, { s: 1, p: '事件二：华歆“废书出看”，说明他羡慕权贵、读书不专心' }, { s: 1, p: '结论：管宁认为两人志趣不同，不能再做朋友' }] },
    { type: 'open', passage: 'guan', q: '翻译：宁割席分坐，曰：“子非吾友也。”',
      ref: '<p>管宁割开坐席，和华歆分开坐，说：“你不是我的朋友了。”</p>',
      points: [{ s: 1, p: '“割席分坐”译为“割开坐席分开坐”' }, { s: 1, p: '“子”译为“你”，“非”译为“不是”，译出判断语气' }] },
    { type: 'fill', passage: 'maiyou', q: '解释加点词：有卖油翁<span class="dot-em">释</span>担而立。', answer: ['放下', '放'],
      explain: '卖油翁放下担子站着，“释”是放下。' },
    { type: 'choice', passage: 'maiyou', q: '下列对文章内容的理解，<b>不正确</b>的一项是：', options: [
        '陈尧咨亲自取来葫芦，用杓子舀油从钱孔注入，铜钱一点没湿',
        '陈尧咨擅长射箭，当时没有人比得上，他也因此自夸',
        '卖油翁看陈尧咨射箭，站了很久都不离开',
        '陈尧咨最后笑着把卖油翁打发走了'], answer: 0,
      explain: '取葫芦、酌油的是卖油翁，不是陈尧咨，这是“张冠李戴”。' },
    { type: 'choice', passage: 'maiyou', q: '下列对“见其发矢十中八九，但微颔之”的理解，正确的一项是：', options: [
        '只是微微点头，表示略有赞许但并不惊叹',
        '但是微微点头，表示非常佩服',
        '但是用下巴指着他，表示看不起',
        '只是微微摇头，表示完全否定'], answer: 0,
      explain: '“但”是“只”，不是今天表转折的“但是”；“颔”是点头。卖油翁觉得射箭十中八九并不稀奇，只是手熟罢了。把“但”理解为“但是”属于曲解词义。' },
    { type: 'open', passage: 'maiyou', q: '文中哪些语句写出了卖油翁对陈尧咨射箭的态度？这是一种怎样的态度？（2 分）',
      ref: '<p>语句：“睨之久而不去”“但微颔之”。态度：卖油翁斜着眼看，只是微微点头，对陈尧咨的射技略有赞许，但并不惊叹佩服，认为不过是“手熟”罢了。</p>',
      points: [{ s: 1, p: '找出语句：“睨之久而不去”“但微颔之”（答出一处即可得分）' }, { s: 1, p: '概括态度：略有赞许，但不以为奇（不惊叹）' }] },
    { type: 'open', passage: 'maiyou', q: '陈尧咨射箭“十中八九”，卖油翁为什么只是“微颔之”？（2 分）',
      ref: '<p>因为卖油翁认为射箭技艺高超并没有什么奥妙，“无他，但手熟尔”，只是熟能生巧的结果；他自己倒油也能做到“自钱孔入，而钱不湿”，所以对陈尧咨的射技只是略有赞许，并不惊奇。</p>',
      points: [{ s: 1, p: '卖油翁认为射技高只是“手熟”，没什么奥妙' }, { s: 1, p: '他自己酌油也同样熟练（自钱孔入，而钱不湿），所以不以为奇' }] },
    { type: 'open', passage: 'maiyou', q: '结合文章内容，分析卖油翁是一个怎样的人。（3 分）',
      ref: '<p>卖油翁技艺纯熟：酌油时“自钱孔入，而钱不湿”；他不卑不亢：面对“忿然”的陈尧咨，不害怕也不争吵，而是用倒油的事实来讲道理；他谦虚：说“我亦无他，惟手熟尔”，不炫耀自己的本领。</p>',
      points: [{ s: 1, p: '技艺纯熟：“自钱孔入，而钱不湿”' }, { s: 1, p: '不卑不亢：面对陈尧咨的发怒，用事实说话' }, { s: 1, p: '谦虚：“我亦无他，惟手熟尔”' }],
      explain: '答人物题用“品质＋依据”的格式，每个品质都要能在原文找到依据。' },
    { type: 'choice', passage: 'maiyou', q: '对陈尧咨这个人物的分析，最全面的一项是：', options: [
        '射技高超，骄傲自负，但最终也能接受别人的道理',
        '射技高超，骄傲自负，是个反面人物',
        '射技一般，却爱吹嘘',
        '谦虚好学，虚心向卖油翁请教'], answer: 0,
      explain: '人物分析要看全篇：开头“善射，当世无双”“以此自矜”，中间“忿然”，结尾“笑而遣之”，说明他也接受了卖油翁的道理。只说骄傲是以偏概全。' },
    { type: 'open', passage: 'maiyou', q: '这个故事告诉我们什么道理？（2 分）',
      ref: '<p>熟能生巧：任何技能只要反复练习，就能达到熟练、精巧的程度。同时也告诉我们，即使有一技之长，也不应骄傲自满。</p>',
      points: [{ s: 1, p: '熟能生巧：技能来自反复练习' }, { s: 1, p: '有长处也不应骄傲自满（或：要谦虚）' }],
      explain: '道理从结局和人物言行反推：卖油翁“惟手熟尔”说出熟能生巧；陈尧咨“自矜”被说服，提醒人不要骄傲。' },
    { type: 'choice', passage: 'taoyuan', q: '下列对文章内容的理解，<b>不正确</b>的一项是：', options: [
        '渔人问村里人现在是什么朝代，村里人回答不知道有汉朝',
        '渔人因为桃花林很美、很奇特，就继续往前走，想走到林子的尽头',
        '村里人见到渔人很吃惊，问他从哪里来',
        '渔人在桃花源住了几天后告辞离开'], answer: 0,
      explain: '原文“问今是何世”是村里人问渔人，选项把问话的人弄反了，属于张冠李戴。' },
    { type: 'choice', passage: 'taoyuan', q: '下列对文章内容的理解，<b>不正确</b>的一项是：', options: [
        '渔人出来后，按照村里人的嘱咐，没有把桃花源的事告诉任何人',
        '渔人出来时，一路上处处做了标记',
        '太守派人跟着渔人去找，却迷了路，没有找到',
        '刘子骥计划去寻找桃花源，没有实现就病死了'], answer: 0,
      explain: '原文是“及郡下，诣太守，说如此”，渔人把桃花源的事告诉了太守，并没有遵守嘱咐。这个选项与原文相反。' },
    { type: 'choice', passage: 'taoyuan', q: '下列对文章内容的理解，<b>不正确</b>的一项是：', options: [
        '桃花源人的祖先带着妻子和乡邻逃到这个没有出路的地方，从此出不去了',
        '桃花源里的人往来耕作，男女的穿着跟桃花源外的人完全一样',
        '桃花源里的老人和小孩都安闲快乐',
        '渔人把自己所知道的事详细地告诉村里人，他们都感叹惋惜'], answer: 0,
      explain: '“妻子”是妻子和儿女，“绝境”是与人世隔绝的地方，“不复出焉”是不再出去。这个选项按今义理解，属于曲解词义。' },
    { type: 'choice', passage: 'taoyuan', q: '下列对文章内容的理解，<b>不正确</b>的一项是：', options: [
        '太守派去的人因为没有带上渔人，所以迷了路',
        '刘子骥听说这件事后，高兴地计划前往',
        '渔人进洞后走了几十步，眼前才豁然开朗',
        '桃花源里土地平坦开阔，房屋整整齐齐'], answer: 0,
      explain: '原文是“太守即遣人随其往”，派去的人是跟着渔人一起去的，“寻向所志，遂迷”，是找先前的标记时迷了路。说“因为没有带上渔人”是强加因果、与原文不符。' },
    { type: 'choice', passage: 'taoyuan', q: '下列对文章内容的理解，<b>不正确</b>的一项是：', options: [
        '村里所有人一见到渔人，就都邀请他到自己家里吃饭',
        '最先邀请渔人回家的村人设酒杀鸡款待他',
        '其余的人听说后也纷纷把渔人请到自己家里',
        '村里人都拿出酒饭来招待渔人'], answer: 0,
      explain: '原文先是一户人家“便要还家，设酒杀鸡作食”，之后“村中闻有此人，咸来问讯”，再后“余人各复延至其家”。说“所有人一见到渔人就都邀请他”，把先后顺序弄乱了，又以偏概全。' },
    { type: 'open', passage: 'taoyuan', q: '文中哪些语句描写了桃花源人安宁快乐的生活？请摘录两处。（2 分）',
      ref: '<p>①“阡陌交通，鸡犬相闻。”②“其中往来种作，男女衣着，悉如外人。”③“黄发垂髫，并怡然自乐。”（任选两处）</p>',
      points: [{ s: 1, p: '摘录一处正确语句（如“黄发垂髫，并怡然自乐”）' }, { s: 1, p: '摘录另一处正确语句（如“阡陌交通，鸡犬相闻”或“其中往来种作”）' }],
      explain: '信息筛选题要按题目要求的数量摘录原句，抄写准确。' },
    { type: 'open', passage: 'taoyuan', q: '村里人为什么对渔人说“不足为外人道也”？（2 分）',
      ref: '<p>村里人的祖先是为躲避秦朝时的战乱才来到这个与世隔绝的地方的，他们在这里过着安宁快乐的生活。他们不希望外人知道这个地方、来打扰他们，所以嘱咐渔人不值得对外面的人说。</p>',
      points: [{ s: 1, p: '原因：祖先为避乱而来，他们希望保持与世隔绝的安宁生活' }, { s: 1, p: '不希望外人知道、前来打扰' }] },
    { type: 'open', passage: 'taoyuan', q: '作者描绘这样一个桃花源，寄托了怎样的理想？（2 分）',
      ref: '<p>作者描绘了一个没有战乱、人人安居乐业、和平宁静的社会，寄托了他对美好生活的向往和追求，也表达了对当时黑暗现实社会的不满。</p>',
      points: [{ s: 1, p: '向往没有战乱、安居乐业、和平宁静的理想社会' }, { s: 1, p: '表达对现实社会的不满' }],
      explain: '主旨题从文章写了什么（理想社会）推出作者的态度，写成完整的话。' }
  ]
},

/* ================= 课外文言文阅读与比较阅读 ================= */
{
  id: 'w-kewai', title: '课外文言文阅读与比较阅读', short: '课外文言', module: 'wenyan', grade: 9, freq: 3,
  prereqs: ['w-neirong', 'w-yiyu', 'w-jushi2'],
  tip: '福建中考文言文阅读常用课内外比较阅读：课外文段的词语多能从课内迁移，题目一般是解释词语、翻译句子、理解内容和比较异同。',
  learn: [
    { h: '课外文言不用怕：三步读懂', html: `
      <ol>
        <li><b>看标题、注释和出处</b>：标题常告诉你写谁、写什么事；注释是“送分题”的线索，一定要先看。</li>
        <li><b>抓人物和事件</b>：边读边圈出人名，弄清“谁做了什么，结果怎样”。看不懂的个别字先跳过，联系上下文再回头猜。</li>
        <li><b>带着题目回原文</b>：每道题都能在原文找到对应的句子，答案从那几句里来。</li>
      </ol>
      <p class="ex">郑人有且置履者，先自度其足，而置之其坐。（《韩非子·外储说左上》）<span class="zh">有个打算买鞋的郑国人，先自己量好脚的尺码，然后把量好的尺码放在自己的座位上。</span></p>` },
    { h: '课内迁移：用学过的词解新句', html: `
      <p>课外文段里的实词、虚词，大多在课内学过。遇到不会的词，就问自己：<b>课文里哪句见过它？</b></p>
      <table class="tbl">
        <tr><th>课外句子</th><th>课内出处</th><th>解释</th></tr>
        <tr><td>患记问不若人</td><td>又患无硕师名人与游（《送东阳马生序》）</td><td>患：担心</td></tr>
        <tr><td>众兄弟既成诵</td><td>既克，公问其故（《曹刿论战》）</td><td>既：已经，……之后</td></tr>
        <tr><td>迨能倍诵乃止</td><td>去后乃至（《陈太丘与友期行》）</td><td>乃：才</td></tr>
        <tr><td>反归取之</td><td>始一反焉（《愚公移山》）</td><td>反：通“返”，返回</td></tr>
        <tr><td>遽契其舟，曰：“是吾剑之所从坠。”</td><td>是马也（《马说》）</td><td>是：这，这里</td></tr>
        <tr><td>其人弗能应也</td><td>河曲智叟亡以应（《愚公移山》）</td><td>应：回答</td></tr>
      </table>
      <p class="warn">迁移时也要回到句子里检验：同一个字在课外句子中可能用的是另一个意思，读通才算对。</p>` },
    { h: '比较阅读：比什么、怎么答', html: `
      <table class="tbl">
        <tr><th>比较角度</th><th>想一想</th></tr>
        <tr><td>内容</td><td>两文各写了什么事？</td></tr>
        <tr><td>人物</td><td>两个人物有什么共同品质？又各有什么特点？</td></tr>
        <tr><td>观点、道理</td><td>两文说明的道理相同吗？</td></tr>
        <tr><td>写法</td><td>用了什么手法（对比、衬托、托物言志、细节描写）？</td></tr>
        <tr><td>情感</td><td>作者表达的情感有何异同？</td></tr>
      </table>
      <p><b>答题格式</b>：</p>
      <div class="tipbox">相同点：两文都……（概括共同点）。<br>不同点：【甲】文……（结合内容）；【乙】文……（结合内容）。</div>
      <p class="warn">比较题最常丢分的地方：只说相同点不说不同点；或者只下结论，不结合两文的具体内容。同、异都要说，甲、乙都要有依据。</p>` },
    { h: '寓言类短文：读出寓意', html: `
      <p>课外文言中常见《韩非子》《吕氏春秋》《列子》等书里的寓言。读寓言要从“<b>人物犯了什么错</b>”推出道理。</p>
      <p class="ex">楚人有涉江者，其剑自舟中坠于水，遽契其舟，曰：“是吾剑之所从坠。”舟止，从其所契者入水求之。舟已行矣，而剑不行，求剑若此，不亦惑乎？（《吕氏春秋·察今》）<span class="zh">有个渡江的楚国人，他的剑从船上掉进水里，他急忙在船上刻了记号，说：“这里是我的剑掉下去的地方。”船停了，他从刻记号的地方下水找剑。船已经走了，可是剑没有走，像这样找剑，不是很糊涂吗？</span></p>
      <p>错误：船在动，剑不动，他却按船上的记号找剑。→ 寓意：<b>事物是发展变化的，不能用静止的眼光看问题。</b></p>
      <div class="rhyme">课外文言先看注，<br>人物事件心中数；<br>课内词义来迁移，<br>比较同异都要述。</div>` }
  ],
  passages: {
    bijiao: { title: '阅读下面两段文言文，完成后面的题目。', html: `
      <p class="noindent"><b>【甲】</b></p>
      <p>余幼时即嗜学。家贫，无从致书以观，每假借于藏书之家，手自笔录，计日以还。天大寒，砚冰坚，手指不可屈伸，弗之怠。录毕，走送之，不敢稍逾约。以是人多以书假余，余因得遍观群书。</p>
      <p class="noindent" style="text-align:right">（节选自宋濂《送东阳马生序》）</p>
      <p class="noindent"><b>【乙】</b></p>
      <p>司马温公幼时，患记问不若人，群居讲习，众兄弟既成诵，游息矣；独下帷绝编，迨能倍诵乃止。用力多者收功远，其所精诵，乃终身不忘也。温公尝言：“书不可不成诵，或在马上，或中夜不寝时，咏其文，思其义，所得多矣。”</p>
      <p class="noindent" style="text-align:right">（据朱熹《三朝名臣言行录》，有改动）</p>
      <p class="noindent" style="font-size:14px">【注】司马温公：司马光，死后追封温国公。记问：记诵。下帷：放下帷幕，指专心读书。绝编：形容反复诵读（编，古代穿竹简的绳子）。倍诵：背诵（倍，通“背”）。</p>` },
    maili: { title: '阅读下面的文言文，完成后面的题目。', html: `
      <p style="text-align:center;text-indent:0"><b>郑人买履</b>（选自《韩非子·外储说左上》）</p>
      <p>郑人有且置履者，先自度其足，而置之其坐。至之市，而忘操之。已得履，乃曰：“吾忘持度。”反归取之。及反，市罢，遂不得履。人曰：“何不试之以足？”曰：“宁信度，无自信也。”</p>
      <p class="noindent" style="font-size:14px">【注】且：将要。置：购买。履：鞋。持度：带上量好的尺码。坐：通“座”，座位。操：拿。罢：结束，散了。</p>` },
    lianlou: { title: '阅读下面两段文言文，完成后面的题目。', html: `
      <p class="noindent"><b>【甲】陋室铭</b>（刘禹锡）</p>
      <p>山不在高，有仙则名。水不在深，有龙则灵。斯是陋室，惟吾德馨。苔痕上阶绿，草色入帘青。谈笑有鸿儒，往来无白丁。可以调素琴，阅金经。无丝竹之乱耳，无案牍之劳形。南阳诸葛庐，西蜀子云亭。孔子云：何陋之有？</p>
      <p class="noindent"><b>【乙】爱莲说</b>（周敦颐）</p>
      <p>水陆草木之花，可爱者甚蕃。晋陶渊明独爱菊。自李唐来，世人甚爱牡丹。予独爱莲之出淤泥而不染，濯清涟而不妖，中通外直，不蔓不枝，香远益清，亭亭净植，可远观而不可亵玩焉。</p>
      <p>予谓菊，花之隐逸者也；牡丹，花之富贵者也；莲，花之君子者也。噫！菊之爱，陶后鲜有闻。莲之爱，同予者何人？牡丹之爱，宜乎众矣。</p>
      <p class="noindent" style="font-size:14px">【注】灵：神异。惟：表示加强肯定语气。馨：能散布很远的香气，这里指德行美好。鸿儒：博学的人。白丁：平民，指没有功名的人。案牍：官府文书。蕃：多。濯：洗。涟：水波。妖：艳丽。亵：亲近而不庄重。宜：应当。</p>` }
  },
  examples: [
    { type: 'choice', q: '阅读《刻舟求剑》，下列对这则寓言寓意的理解，最恰当的一项是：<div class="passage"><p>楚人有涉江者，其剑自舟中坠于水，遽契其舟，曰：“是吾剑之所从坠。”舟止，从其所契者入水求之。舟已行矣，而剑不行，求剑若此，不亦惑乎？</p></div>', options: [
        '要用发展变化的眼光看问题，不能拘泥固守、不知变通',
        '丢了东西要及时做记号，才能找回来',
        '过江时要小心，不要把东西掉进水里',
        '做事要果断，想到就马上去做'], answer: 0,
      explain: '楚人错在船已经行进，剑却留在原处，他却仍按船上的记号找剑。寓意是：情况变了，做法也要跟着变，不能用静止的眼光看问题。' },
    { type: 'open', q: '翻译：“舟已行矣，而剑不行，求剑若此，不亦惑乎？”（《刻舟求剑》）',
      ref: '<p>船已经走了，可是剑没有走，像这样找剑，不是很糊涂吗？</p>',
      points: [{ s: 1, p: '“而”译出转折（可是、但是）' }, { s: 1, p: '“若此”译为“像这样”' }, { s: 1, p: '“不亦……乎”译为“不是……吗”，“惑”译为“糊涂”' }],
      explain: '“不亦……乎”是反问的固定格式，和“不亦说乎”一样，翻译时要译出反问语气。' },
    { type: 'choice', q: '读《郑人买履》时，遇到“先自度其足，而置之其<span class="dot-em">坐</span>”中的“坐”，确定它意思最可靠的做法是：<div class="passage"><p class="noindent">（文后注释）坐：通“座”，座位。</p></div>', options: [
        '先看文后注释：“坐”通“座”，座位',
        '按今天的意思理解为“坐下”',
        '跳过不管，反正不影响做题',
        '凭感觉猜是“坐车”'], answer: 0,
      explain: '读课外文言的第一步是看标题、注释和出处。注释是“送分题”的线索，通假字、难词往往都注出来了。“置之其坐”就是把（量好的尺码）放在自己的座位上。' },
    { type: 'choice', q: '阅读《守株待兔》，联系课内所学，下列加点词解释<b>不正确</b>的一项是：<div class="passage"><p>宋人有耕者。田中有株，兔走触株，折颈而死。因释其耒而守株，冀复得兔。兔不可复得，而身为宋国笑。</p></div>', options: [
        '兔<span class="dot-em">走</span>触株：步行（联系今义）',
        '因<span class="dot-em">释</span>其耒而守株：放下（联系“有卖油翁释担而立”）',
        '兔不可<span class="dot-em">复</span>得：再（联系“不复出焉”）',
        '而身<span class="dot-em">为</span>宋国笑：被'], answer: 0,
      explain: '“兔走触株”是兔子奔跑着撞到树桩上，“走”是古义“跑”，可以迁移《送东阳马生序》“录毕，走送之”。按今义理解成“步行”就错了。课内迁移时要找意思相通的课内句子，并回到原句检验。' },
    { type: 'open', q: '比较【甲】【乙】两文在写法上的异同。（3 分）<div class="passage"><p class="noindent">【甲】斯是陋室，惟吾德馨。苔痕上阶绿，草色入帘青。谈笑有鸿儒，往来无白丁。……孔子云：何陋之有？（刘禹锡《陋室铭》）</p><p class="noindent">【乙】予独爱莲之出淤泥而不染，濯清涟而不妖……予谓菊，花之隐逸者也；牡丹，花之富贵者也；莲，花之君子者也。（周敦颐《爱莲说》）</p></div>',
      ref: '<p>相同点：两文都运用了托物言志的写法，借陋室、莲花表达作者的志趣和品格。</p><p>不同点：【甲】文借写陋室的环境、交往和生活，表现主人“德馨”，以陋室不陋来表明自己安贫乐道的情怀；【乙】文借描写莲的形象，并以菊、牡丹作衬托，突出莲的“君子”品格，表明自己洁身自好、不与世俗同流合污的志向。</p>',
      points: [{ s: 1, p: '相同点：都用托物言志' }, { s: 1, p: '甲文：借陋室写主人“德馨”，表现安贫乐道' }, { s: 1, p: '乙文：用菊、牡丹衬托莲，表现洁身自好的君子品格' }],
      explain: '比较题的格式：“相同点：两文都……；不同点：【甲】文……；【乙】文……”。同和异都要说，甲乙都要结合具体内容，这样才能拿全分。' },
    { type: 'choice', q: '比较【甲】《陋室铭》和【乙】《爱莲说》表达的情感，下列说法正确的一项是：', options: [
        '都表达了作者高洁的品格；甲文侧重安贫乐道，乙文侧重洁身自好、不同流合污',
        '都表达了作者对富贵生活的向往',
        '甲文表达对陋室的嫌弃，乙文表达对莲花的喜爱',
        '两文情感完全相同，没有区别'], answer: 0,
      explain: '甲文说“斯是陋室，惟吾德馨”“何陋之有”，表现安贫乐道；乙文以莲自比，表现不慕名利、洁身自好。两文都写高洁的品格，但侧重点不同。' }
  ],
  tests: [
    { type: 'choice', passage: 'bijiao', q: '下列加点词的解释，<b>不正确</b>的一项是：', options: [
        '每<span class="dot-em">假</span>借于藏书之家：借',
        '<span class="dot-em">患</span>记问不若人：担心',
        '众兄弟<span class="dot-em">既</span>成诵：已经',
        '计日以<span class="dot-em">还</span>：还是'], answer: 3,
      explain: '“计日以还”是计算着日子按时归还，“还”读 huán，是“归还”。' },
    { type: 'fill', passage: 'bijiao', q: '解释加点词：独下帷绝编，<span class="dot-em">迨</span>能倍诵乃止。', answer: ['等到', '到', '直到', '等'],
      explain: '“迨能倍诵乃止”：等到能背诵了才停止。“迨”是“等到”。“乃”可迁移课内“去后乃至”，是“才”。' },
    { type: 'open', passage: 'bijiao', q: '翻译：录毕，走送之，不敢稍逾约。',
      ref: '<p>抄写完毕，（我）跑着把书送还给人家，不敢稍微超过约定的期限。</p>',
      points: [{ s: 1, p: '“走”译为“跑”' }, { s: 1, p: '“逾约”译为“超过约定的期限”' }, { s: 1, p: '“稍”译为“稍微”，补出省略的内容，句意通顺' }] },
    { type: 'open', passage: 'bijiao', q: '翻译：书不可不成诵。',
      ref: '<p>读书不能不背诵下来。</p>',
      points: [{ s: 1, p: '“不可不”译为“不能不”，保留双重否定的语气' }, { s: 1, p: '“成诵”译为“（能够）背诵下来”' }] },
    { type: 'open', passage: 'bijiao', q: '【甲】【乙】两文都写了读书，宋濂和司马光有什么共同之处？两人的读书经历又有什么不同？请结合文章内容分析。',
      ref: '<p>相同点：两人都勤奋刻苦、好学。</p><p>不同点：【甲】文中宋濂家里贫穷，没有书读，靠向别人借书、亲手抄书来读，天寒手冻也不懈怠，并且守信按期还书；【乙】文中司马光担心自己记诵不如别人，别人休息时他仍独自反复诵读，直到能背诵才停止，还主张读书要背诵、要边读边思考。</p>',
      points: [{ s: 1, p: '相同点：都勤奋刻苦、好学' }, { s: 1, p: '甲文不同点：家贫借书抄书，天寒不懈，守信还书' }, { s: 1, p: '乙文不同点：担心记诵不如人，反复诵读直到能背，读书注重背诵和思考' }] },
    { type: 'fill', passage: 'bijiao', q: '联系《送东阳马生序》“又患无硕师名人与游”，解释加点词：司马温公幼时，<span class="dot-em">患</span>记问不若人。', answer: ['担心', '忧虑', '担忧', '忧虑担心'],
      explain: '课内迁移：“患”在这里与课内一样，是“担心、忧虑”：司马光小时候，担心自己记诵诗书的能力不如别人。' },
    { type: 'choice', passage: 'bijiao', q: '读【乙】文时，“迨能<span class="dot-em">倍</span>诵乃止”中的“倍”不认识，最好的解决办法是：', options: [
        '先看文后注释：倍，通“背”，“倍诵”即背诵',
        '按今义理解为“加倍”',
        '把这句跳过，不影响理解',
        '查不到就随便写一个意思'], answer: 0,
      explain: '读课外文言要先看注释，注释已经说明“倍”通“背”。“迨能倍诵乃止”：等到能背诵了才停止。' },
    { type: 'choice', passage: 'bijiao', q: '下列对【甲】【乙】两文的理解，<b>不正确</b>的一项是：', options: [
        '宋濂因为家里有很多藏书，所以能读遍群书',
        '宋濂借书抄写，按约定的日期归还，所以人们愿意借书给他',
        '司马光在别人游玩休息时，独自反复诵读',
        '司马光认为读书要能背诵，还要边读边思考'], answer: 0,
      explain: '甲文说“家贫，无从致书以观”，宋濂家里穷，没有办法得到书，是靠借书抄书才“遍观群书”的。选项与原文相反。' },
    { type: 'open', passage: 'bijiao', q: '【甲】【乙】两文对我们的学习有什么共同的启示？（2 分）',
      ref: '<p>学习要勤奋刻苦、持之以恒，不怕困难（宋濂天寒手冻仍抄书不懈，司马光别人休息时仍反复诵读）；读书要扎实用功，下的功夫越多，收获越大（“用力多者收功远”）。</p>',
      points: [{ s: 1, p: '启示一：学习要勤奋刻苦、不怕困难（结合两文）' }, { s: 1, p: '启示二：读书要扎实用功，功夫越深收获越大（或：读书要熟读成诵、边读边思考）' }],
      explain: '比较阅读中的“道理、启示”题，要从两个人物共同的做法推出道理，最好结合两文内容来说。' },
    { type: 'choice', passage: 'maili', q: '“先自<span class="dot-em">度</span>其足”中，“度”的读音和意思是：', options: ['duó，量', 'dù，尺码', 'dù，度过', 'duó，猜测'], answer: 0,
      explain: '“先自度其足”是先自己量好脚的尺寸，“度”是动词，读 duó，意思是“量”。后文“吾忘持度”的“度”是名词，读 dù，指量好的尺码。' },
    { type: 'choice', passage: 'maili', q: '下列对文章内容的理解，<b>不正确</b>的一项是：', options: [
        '郑人在家量好了尺码，到集市时却忘了带',
        '郑人回家去取尺码，等他回到集市，集市已经散了',
        '有人建议他用自己的脚试鞋，他却宁可相信尺码',
        '郑人最后用自己的脚试穿，买到了合适的鞋子'], answer: 3,
      explain: '原文是“及反，市罢，遂不得履”：等他回来时集市已经散了，最终没有买到鞋。他也不肯用脚试，说“宁信度，无自信也”。' },
    { type: 'open', passage: 'maili', q: '这则寓言讽刺了什么样的人？给了我们什么启示？',
      ref: '<p>讽刺了那些死守教条、只相信条文而不尊重客观实际的人。启示我们：做事要从实际出发，懂得灵活变通，不能墨守成规。</p>',
      points: [{ s: 1, p: '讽刺对象：死守教条、不顾实际的人（只信尺码不信自己的脚）' }, { s: 1, p: '启示：做事要从实际出发，灵活变通' }] },
    { type: 'choice', passage: 'maili', q: '根据文后注释，“至之市，而忘<span class="dot-em">操</span>之”中“操”的意思是：', options: ['拿', '操练', '操心', '做'], answer: 0,
      explain: '注释写明“操：拿”。到了集市，却忘了带上（量好的尺码）。读课外文言先看注释，这类题就能直接得分。' },
    { type: 'fill', passage: 'maili', q: '联系《陈涉世家》“辍耕之垄上”，解释加点词：至<span class="dot-em">之</span>市。', answer: ['到', '往', '去', '前往'],
      explain: '“之”后面跟地点“市”，是动词“到、往”，和“辍耕之垄上”的“之”相同。' },
    { type: 'fill', passage: 'maili', q: '联系《愚公移山》“始一反焉”，解释加点词：<span class="dot-em">反</span>归取之。', answer: ['通返返回', '同返返回', '返回', '返', '回', '通返', '反通返返回'],
      explain: '“反”通“返”，返回。郑人返回家去取尺码。' },
    { type: 'choice', passage: 'maili', q: '“<span class="dot-em">及</span>反，市罢，遂不得履”中“及”的意思是：', options: ['等到', '和', '比得上', '涉及'], answer: 0,
      explain: '等到他返回集市，集市已经散了，“及”是“等到”。' },
    { type: 'open', passage: 'maili', q: '翻译：何不试之以足？（2 分）',
      ref: '<p>为什么不用（自己的）脚试一试（鞋）呢？</p>',
      points: [{ s: 1, p: '“何不……”译为“为什么不……呢”' }, { s: 1, p: '“试之以足”按状语后置调为“以足试之”，译为“用脚试一试”' }],
      explain: '“试之以足”是状语后置（介词短语“以足”后置），即“以足试之”。' },
    { type: 'fill', passage: 'lianlou', q: '联系课内所学，解释加点词：菊之爱，陶后<span class="dot-em">鲜</span>有闻。', answer: ['少', '很少'],
      explain: '“鲜”读 xiǎn，少。可以联想成语“鲜为人知”。' },
    { type: 'choice', passage: 'lianlou', q: '下列对【甲】【乙】两文的理解，<b>不正确</b>的一项是：', options: [
        '【甲】文作者认为陋室简陋，所以借诸葛庐、子云亭来自我安慰',
        '【甲】文“谈笑有鸿儒，往来无白丁”写出主人交往的都是有学问的人',
        '【乙】文“出淤泥而不染，濯清涟而不妖”写出莲洁身自好、不同流合污的品格',
        '【乙】文用菊、牡丹来衬托莲，突出莲是“花之君子”'], answer: 0,
      explain: '甲文结尾“孔子云：何陋之有？”是说陋室并不简陋；用诸葛庐、子云亭类比，是表明自己也有古代贤人的志趣，不是“自我安慰”。' },
    { type: 'open', passage: 'lianlou', q: '两文都用了托物言志的写法。请说说【甲】【乙】两文分别借什么物、言什么志。（2 分）',
      ref: '<p>【甲】文借陋室，表达了作者安贫乐道、高洁傲岸的情操；【乙】文借莲花，表达了作者洁身自好、不与世俗同流合污的品格。</p>',
      points: [{ s: 1, p: '甲文：借陋室，言安贫乐道（品德高尚）之志' }, { s: 1, p: '乙文：借莲花，言洁身自好、不同流合污之志' }] },
    { type: 'open', passage: 'lianlou', q: '比较两文表达的思想感情有何异同。（3 分）',
      ref: '<p>相同点：两文都表达了作者高洁的品格和不慕名利的志趣。</p><p>不同点：【甲】文通过写陋室中的生活和交往，表现作者安贫乐道的情怀；【乙】文通过赞美莲花，表达作者洁身自好的品格，同时含有对世人追名逐利（甚爱牡丹）的不满。</p>',
      points: [{ s: 1, p: '相同点：都表达高洁的品格、不慕名利' }, { s: 1, p: '甲文：安贫乐道' }, { s: 1, p: '乙文：洁身自好，对追名逐利世风的不满' }] },
    { type: 'choice', passage: 'lianlou', q: '题目是“比较两文在写法上的异同”。下面四位同学的回答，最完整、最规范的一项是：', options: [
        '相同点：都用托物言志。不同点：【甲】文借陋室写主人“德馨”；【乙】文用菊、牡丹衬托莲，突出君子品格',
        '两文都用了托物言志的写法',
        '【甲】文借陋室言志，【乙】文借莲花言志',
        '两文写法不同，【乙】文用了衬托'], answer: 0,
      explain: '比较题最常丢分的地方：只说相同点不说不同点，或者只下结论不结合内容。同、异都要说，甲、乙都要有依据。' },
    { type: 'choice', q: '阅读《揠苗助长》，这则寓言的寓意是：<div class="passage"><p>宋人有闵其苗之不长而揠之者，芒芒然归，谓其人曰：“今日病矣！予助苗长矣！”其子趋而往视之，苗则槁矣。</p></div>（选自《孟子·公孙丑上》。闵：担心。揠：拔。病：疲惫。槁：枯萎）', options: [
        '做事要遵循事物发展的规律，急于求成反而会把事情办坏',
        '种庄稼要勤劳，每天都要到田里去',
        '做事要果断，想到就去做',
        '帮助别人是一件很累的事'], answer: 0,
      explain: '宋人错在违背禾苗生长的规律，把苗往上拔，结果禾苗全枯死了。读寓言要从“人物犯了什么错”推出道理。' },
    { type: 'open', q: '阅读《守株待兔》，回答：这个宋人犯了什么错？这则寓言告诉我们什么道理？（2 分）<div class="passage"><p>宋人有耕者。田中有株，兔走触株，折颈而死。因释其耒而守株，冀复得兔。兔不可复得，而身为宋国笑。</p></div>（株：露出地面的树桩。释：放下。耒：农具。冀：希望）',
      ref: '<p>错误：他把兔子撞死在树桩上这种偶然的事当成必然，放下农具守在树桩旁，希望再得到兔子。道理：不能把偶然当作必然，不能存侥幸心理、不劳而获，要靠自己的努力。</p>',
      points: [{ s: 1, p: '错误：把偶然的事当成必然，放下农具守株待兔' }, { s: 1, p: '道理：不能心存侥幸、不劳而获（或：不能把偶然当必然）' }] }
  ]
}

